/* 北京师范大学学生综合测评管理系统: dependency-free UI. Credentials remain in HttpOnly cookies.
 * All server/user strings are escaped at the HTML boundary. No eval or agents.
 */
'use strict';
function initialState(){return {me:null,project:null,projects:[],students:[],staff:[],folders:[],folder:null,trash:false,
  ruleDraft:null,dirtyRules:false,files:[],uploading:false,reviewFilter:'attention',reviewStatuses:['unlabeled','untrusted','system_error','manual'],reviewId:null,
  calc:null,publicEdit:null,publicRows:[],academic:null,routeSeq:0};}
const S=initialState();
function clearSessionState(){BNUCollections.close();BNUCapture.cancel();if(typeof clearFeedbackDraft==='function')clearFeedbackDraft();for(const f of S.files||[])if(f.url)URL.revokeObjectURL(f.url);for(const key of Object.keys(S))delete S[key];Object.assign(S,initialState());const d=document.getElementById("dialog");if(d?.open)d.close();document.getElementById("dialog-content")?.replaceChildren();}
const A={},F={};
function hasUnsavedWork(){return !!(S.dirtyRules||S.formDirty||S.files.some(f=>f.state!=='done'));}
function markDirty(){S.formDirty=true;}
function clearDirty(){S.formDirty=false;}
const statuses={unlabeled:'未标注',valid:'有效',untrusted:'不可信',out_of_scope:'不属于加分情形',out_of_period:'不在加分时间',manual:'需人工判断',invalid_image:'图片无效',system_error:'系统异常'};
const stageNames={setup:'准备中',scheduled:'等待开放',submission:'材料提交',review:'审核中',publication:'公示中',closed:'已结项',archived:'已归档'};
const steps=[['overview','总览'],['setup','准备工程'],['submission','提交材料'],['review','材料标注'],['public','统一信息录入'],['calculation','计算结果'],['publication','公示与申诉'],['archive','导出与存档']];
const reasons={missing_evidence:'缺少佐证 / 申请补交',unclear_image:'图片不清晰',wrong_classification:'分类有疑问',wrong_score:'分值有疑问',system_failure:'提交时遇到系统问题',other:'其他需老师处理的情况'};
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',folder:'M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',check:'M20 6L9 17l-5-5',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4',download:'M12 3v13 M7 11l5 5 5-5 M4 16v4h16v-4',search:'M21 21l-6-6 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',close:'M6 6l12 12 M18 6L6 18',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z M13 6a3 3 0 0 1 3-3h5v16h-4a4 4 0 0 0-4 2',message:'M21 15a3 3 0 0 1-3 3H8l-5 4V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3z M7 7h10 M7 11h7',code:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',logout:'M9 21H4V3h5 M13 8l5 4-5 4 M8 12h13',camera:'M3 7h4l2-3h6l2 3h4v14H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',image:'M3 3h18v18H3z M3 17l6-6 5 5 3-3 4 4 M9 7h.01',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',dots:'M5 12h.01 M12 12h.01 M19 12h.01',edit:'M16 3l5 5-12 12-6 1 1-6z M13 6l5 5',archive:'M3 3h18v5H3z M5 8v13h14V8 M10 12h4',menu:'M3 6h18 M3 12h18 M3 18h18',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 13-2l2 2 M19 17a8 8 0 0 1-13 2l-2-2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',chart:'M4 21V3 M4 21h18 M8 17v-5 M13 17V7 M18 17V4',copy:'M9 9h12v12H9z M5 15H3V3h12v2',mail:'M3 5h18v14H3z M3 5l9 7 9-7'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.file}"/></svg>`;}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function attrs(data={}){return Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ');}
function btn(action,text,cls='',data={},ic=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs(data)}>${ic?icon(ic):''}${esc(text)}</button>`;}
function link(text,url,cls='btn secondary',ic=''){return `<a class="${cls}" href="${esc(url)}">${ic?icon(ic):''}${esc(text)}</a>`;}
function tag(text,kind=''){return `<span class="tag ${kind}">${esc(text)}</span>`;}
function statusTag(status){return tag(statuses[status]||status,status==='valid'?'':status==='unlabeled'?'gray':status==='manual'||status==='system_error'?'amber':'red');}
function field(name,label,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(name,label,value='',extra=''){return `<label>${esc(label)}<textarea name="${esc(name)}" ${extra}>${esc(value)}</textarea></label>`;}
function select(name,label,options,value='',extra=''){return `<label>${esc(label)}<select name="${esc(name)}" ${extra}>${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`;}
function fmt(t){if(!t)return '尚未设置';return new Date(t).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function localDate(t){if(!t)return '';const d=new Date(t);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function size(n){return n>1048576?(n/1048576).toFixed(1)+' MB':(n/1024).toFixed(0)+' KB';}
function toast(text,error=false){const d=document.createElement('div');d.className='toast'+(error?' error':'');d.textContent=text;document.getElementById('toasts').append(d);setTimeout(()=>d.remove(),error?9000:5000);}
function explainError(data){
  const detail=data?.detail;
  if(Array.isArray(detail))return detail.map(e=>e.loc.slice(1).join('.')+'：'+e.msg).join('；');
  if(detail&&typeof detail==='object')return detail.message||'请求校验失败，请查看错误清单。';
  return typeof detail==='string'?detail:'请求失败，请稍后再试。';
}
async function api(url,{method='GET',body,raw=false,binary=false}={}){
  const headers={};if(method!=='GET'&&method!=='HEAD'&&S.me?.csrf)headers['X-CSRF-Token']=S.me.csrf;
  if(body!==undefined&&!raw)headers['Content-Type']='application/json';
  let r;try{r=await fetch(url,{method,headers,credentials:'same-origin',body:body===undefined?undefined:raw?body:JSON.stringify(body)});}catch{throw new Error('网络连接中断，未收到保存确认。请保留当前页面并重试；已接收原件和历史版本不会被删除。');}
  if(r.ok&&binary)return {blob:await r.blob(),disposition:r.headers.get('Content-Disposition')};
  const data=await r.json().catch(()=>({}));
  if(!r.ok){if(r.status===401&&S.me){clearSessionState();renderLogin();}if(r.status===428&&S.me)showPassword();throw Object.assign(new Error(explainError(data)),{status:r.status,diagnostics:data?.detail?.errors?data.detail:null});}
  return data;
}
async function allStudents(){const rows=[];for(let offset=0;;offset+=2000){const page=await api('/api/students?offset='+offset+'&limit=2000');rows.push(...page);if(page.length<2000)return rows;}}
const get=id=>document.getElementById(id);
function formData(form){return Object.fromEntries(new FormData(form).entries());}
function modal(title,body,wide=false){const d=get('dialog');d.classList.toggle('wide',wide);get('dialog-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button type="button" class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();if(typeof enhanceCollections==='function')enhanceCollections(get('dialog-content'));}
A.close=()=>get('dialog').close();
function actions(submit='保存',cancel=true){return `<div class="form-actions">${cancel?btn('close','取消','secondary'):''}<button type="submit" class="btn">${esc(submit)}</button></div>`;}
function search(target,placeholder='搜索姓名、学号或内容'){return `<div class="search">${icon('search')}<input type="search" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}" data-filter="${target}"></div>`;}
function heading(title,subtitle='',buttons=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="row wrap">${buttons}</div></div>`;}
function empty(title,text,button=''){return `<div class="empty">${icon('file')}<h2>${esc(title)}</h2><p>${esc(text)}</p>${button}</div>`;}
function navItems(active){let items=S.me.role==='admin'?[['ops','运维概览','shield'],['ops-accounts','账号与学院','users'],['ops-feedback','用户反馈','message'],['ops-audit','系统日志','file']]:S.me.role==='teacher'?[['workspace','工作空间','grid'],['students','学生名册','users'],['public-lists','名单类奖项','file'],['agents','Agent 接口','code']]:[['workspace','我的综测','grid']];return items.map(([id,text,ic])=>`<a class="nav-item ${active===id?'active':''}" href="#/${id}">${icon(ic)}<span>${esc(text)}</span></a>`).join('');}
function shell(content,active='workspace',crumb='工作空间'){
 const role={student:'学生',teacher:'教师',admin:'系统管理员'}[S.me.role];
 get('app').innerHTML=`<aside class="sidebar"><a class="brand" href="#/${S.me.role==='admin'?'ops':'workspace'}"><div class="brand-text"><strong>北京师范大学</strong><small>学生综合测评管理系统</small></div></a><div class="nav-label">${S.me.role==='admin'?'系统管理':'业务功能'}</div><nav>${navItems(active)}</nav><div class="sidebar-bottom"><div class="workspace-tip">${S.me.role==='admin'?'此账户用于系统维护，不具有评分权限。':'请按页面提示完成操作。<br>离开公用电脑前，请退出登录。'}</div><a class="nav-item" href="/manual" target="_blank" rel="noopener">${icon('book')}<span>使用手册</span></a><a class="nav-item" href="/tutorial" target="_blank" rel="noopener">${icon('book')}<span>首次使用图文教程</span></a><button class="nav-item" data-action="feedback">${icon('message')}<span>意见反馈</span></button><div class="account"><div class="avatar">${esc(S.me.name.slice(-2))}</div><div class="grow"><strong>${esc(S.me.name)}</strong><div class="muted small">${role}</div></div><button class="icon-btn" data-action="account" aria-label="账户设置">${icon('settings')}</button></div></div></aside><div class="main-wrap"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-action="menu" aria-label="打开导航">${icon('menu')}</button><div class="breadcrumbs">工作台 &nbsp; / &nbsp; <strong>${esc(crumb)}</strong></div></div><div class="right"><span class="connection">${location.protocol==='https:'?'HTTPS 安全连接':'本机验证 · 非 HTTPS'}</span><span class="small">${esc(S.me.name)}</span><button class="icon-btn" data-action="account" aria-label="账户设置">${icon('settings')}</button></div></header><main class="content" id="main">${content}</main></div>`;
 if(typeof enhanceCollections==='function')enhanceCollections(get('main'));
}
A.menu=()=>modal('工作台导航',`<nav>${navItems('')}</nav><hr>${link('使用手册','/manual','btn secondary','book')} ${link('图文教程','/tutorial','btn secondary','book')} ${btn('feedback','意见反馈','secondary',{},'message')} ${btn('logout','退出登录','ghost',{},'logout')}`);
A.account=()=>modal('账户与安全',`<p><strong>${esc(S.me.name)}</strong> · ${{student:'学生',teacher:'教师',admin:'系统管理员'}[S.me.role]}</p><p class="muted small">密码更新会立即撤销其他登录会话及此账户签发的服务令牌。</p><div class="row wrap">${btn('password','修改密码','',{},'shield')}${btn('logout','退出登录','secondary',{},'logout')}</div>`);
A.logout=async()=>{if(hasUnsavedWork()&&!window.confirm('退出后未保存的修改和未提交的图片将从本机页面清除。已提交的材料不会删除。是否退出？'))return;await api('/api/auth/logout',{method:'POST'});clearSessionState();location.hash='';renderLogin();};
A.password=()=>showPassword();
function showPassword(){modal(S.me?.must_change?'首次登录 · 请设置新密码':'修改密码',`<form data-form="password">${field('old_password','当前/初始密码','','password','required autocomplete="current-password"')}${field('new_password','新密码（至少12个字符）','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('confirm_password','再次输入新密码','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="muted small">初始密码只用于激活账户。请不要沿用姓名、学号或共享口令。</p>${actions('更新密码',!S.me?.must_change)}</form>`);}
F.password=async(form)=>{const d=formData(form);if(d.new_password!==d.confirm_password)throw new Error('两次输入的新密码不一致，请重新核对。');S.me=await api('/api/auth/password',{method:'POST',body:{old_password:d.old_password,new_password:d.new_password}});A.close();toast('密码已更新，其他会话已撤销。');await route();};
function renderLogin(){
 let portal=document.body.dataset.portal||'choose';if(!['student','teacher','admin'].includes(portal))portal='choose';
 const help=portal==='admin'?'忘记密码时，请由持有服务器管理权限的人员使用管理脚本恢复原管理员账户。':portal==='teacher'?'教师账号由系统管理员创建。忘记账号或密码时，请联系系统管理员。':'学生账号由负责教师创建。忘记账号或密码时，请联系负责教师。';
 get('app').innerHTML=`<div class="login-office"><header class="login-header"><h1>北京师范大学学生综合测评管理系统</h1></header><main id="main" class="login-panel">${portal==='choose'?`<h2>欢迎使用</h2><p class="muted">请选择登录入口。系统不开放自行注册。</p><a class="portal-link" href="/login/student">${icon('users')}<div class="grow"><strong>学生登录</strong><small>提交材料、查看个人结果、提出补交申请</small></div>${icon('arrow')}</a><a class="portal-link" href="/login/teacher">${icon('grid')}<div class="grow"><strong>教师登录</strong><small>管理名册、规则、审核、公示和存档</small></div>${icon('arrow')}</a>`:`<h2>${{student:'学生登录',teacher:'教师登录',admin:'系统管理员登录'}[portal]}</h2><p class="muted">请输入已分配的账号和密码。首次登录后需要修改初始密码。</p><form data-form="login"><input name="portal" type="hidden" value="${portal}">${field('username','账号','','text','required autocomplete="username"')}${field('password','密码','','password','required autocomplete="current-password"')}${portal==='admin'?field('totp','动态验证码（生产部署必填）','','text','inputmode="numeric" maxlength="6" autocomplete="one-time-code"'):''}<div id="login-error" role="alert"></div><button class="btn full" type="submit">登录</button></form>${portal!=='admin'?'<p class="login-foot"><a href="/">返回入口选择</a></p>':''}<p class="login-foot">${help}</p>`}<div class="login-help"><a href="/tutorial#login" target="_blank" rel="noopener">首次登录操作教程</a><a href="/manual" target="_blank" rel="noopener">使用手册</a></div></main><footer class="login-footer">请使用学院通知的网址登录。请勿向他人提供密码或动态验证码。</footer></div>`;
}
F.login=async(form)=>{const d=formData(form);try{S.me=await api(d.portal==='admin'?'/api/ops/login':'/api/auth/login',{method:'POST',body:d});if(S.me.must_change)showPassword();else{if(!location.hash)location.hash=S.me.role==='admin'?'#/ops':'#/workspace';await route();}}catch(e){get('login-error').innerHTML=`<div class="login-error">${esc(e.message)}</div>`;}};
function credentialsModal(credentials,title='新账号已创建'){if(!credentials.length){toast('已有学生身份已匹配，未重置原密码。');return;}S.credentials=credentials;modal(title,`<div class="callout amber">初始密码只显示这一次。请保存到受控位置并逐人分发，不要发到班级群。首次登录必须修改。</div><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>姓名</th><th>账号</th><th>初始密码</th></tr></thead><tbody>${credentials.map(r=>`<tr><td>${esc(r.name||'')}</td><td>${esc(r.username)}</td><td><code>${esc(r.initial_password)}</code></td></tr>`).join('')}</tbody></table></div><div class="form-actions">${btn('credentials','保存一次性凭据','',{},'download')}${btn('close','已妥善保存','secondary')}</div>`,true);}
A.credentials=()=>{const lines=[['姓名','账号','初始密码'],...S.credentials.map(x=>[x.name||'',x.username,x.initial_password])];saveBlob(new Blob(['\ufeff'+lines.map(r=>r.map(x=>'"'+String(x).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv'}),'一次性初始凭据-请私密保存.csv');};
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function pid(){return S.project.id;}
function purl(tab='overview'){return `#/project/${pid()}/${tab}`;}
async function loadProject(id){S.project=await api('/api/projects/'+encodeURIComponent(id));return S.project;}
async function updateProject(url,method,body){const result=await api(url,{method,body});S.project=result;return result;}
function projectHeader(tab){const p=S.project;return heading(p.title,`${p.meta.year} · ${p.meta.class_name} · ${p.meta.responsible||'负责教师未填写'}`,`${p.meta.test_only?tag('测试工程 · 非正式','amber'):''}${tag(stageNames[p.state]||p.state,p.state==='publication'?'':'gray')}${S.me.role==='teacher'&&p.can_review?btn('export-tables','导出表格','secondary',{},'download'):''}${link('返回工作空间','#/workspace','btn secondary','back')}`)+`<nav class="stepper" aria-label="综测工作阶段">${(p.can_review?steps.slice(1):[['submission','提交材料'],['publication','我的结果']]).map(([id,label],i)=>`<a class="step ${tab===id?'active':''}" href="${purl(id)}"><span class="step-no">${i}</span>${esc(label)}</a>`).join('')}</nav>`;}
function paintProject(tab,html){shell(projectHeader(tab)+html,'workspace',S.project.meta.class_name+' / '+(steps.find(x=>x[0]===tab)?.[1]||'总览'));}
async function workspace(){
 const p=await api('/api/projects?trashed='+S.trash);S.projects=p;
 if(S.me.role==='teacher')S.folders=await api('/api/folders');
 const items=p.filter(x=>!S.folder||(S.folder==='root'?!x.folder_id:x.folder_id===S.folder));
 const stats=p.reduce((a,x)=>{a.students+=x.student_count;a.evidence+=x.evidence_count;return a;},{students:0,evidence:0});
 const name=S.me.role==='student'?'我的综测':'工作空间';
 const controls=S.me.role==='teacher'?`${btn('new-project','新建综测工程','',{},'plus')}${btn('import-project','导入工程','secondary',{},'upload')}${link('工程目录表','/api/export-tables/workspace','btn secondary','download')}${link('全部授权工程成果','/api/export-tables/achievements','btn secondary','download')}`:'';
 let html=heading(name,S.me.role==='student'?'请选择本班工程。学生仅需上传清晰的证明图片，无需填写分数。':'每个工程对应一个班级。请选择已有工程，或新建工程。',controls);
 html+=`<section class="card welcome-panel"><div><h2>${esc(S.me.name)}，您好。</h2><p class="muted small">${S.me.role==='student'?'请选择下方的班级工程，上传证明图片。评分在教师发布公示后显示。':'新建工程前，请先导入学生名册。已有工程可从下方列表进入，按阶段完成设置和审核。'}</p></div><div class="row wrap">${link('首次使用图文教程','/tutorial','btn secondary','book')}${link('使用手册','/manual','btn secondary','book')}</div></section>`;
 if(S.me.role==='teacher')html+=`<div class="grid4"><div class="card stat"><div class="small">工程数量</div><div class="number">${p.length}</div><div class="small">一份工程对应一个班级</div></div><div class="card stat"><div class="small">参评人次</div><div class="number">${stats.students}</div><div class="small">按可访问工程汇总</div></div><div class="card stat"><div class="small">独立提交材料</div><div class="number">${stats.evidence}</div><div class="small">不含名单类奖项行</div></div><div class="card stat"><div class="small">正在公示</div><div class="number">${p.filter(x=>x.state==='publication').length}</div><div class="small">只向本人展示结果</div></div></div>`;
 html+=`<div class="toolbar"><div class="row"><h2 style="margin:0">${S.trash?'回收站':'测评工程'}</h2>${tag(items.length+' 个','gray')}</div><div class="row grow" style="justify-content:flex-end">${search('project-list','搜索工程、年度或班级')}${S.me.role==='teacher'?btn('new-folder','新建文件夹','secondary mini',{},'folder')+btn('toggle-trash',S.trash?'返回工程':'回收站','secondary mini',{},S.trash?'back':'trash'):''}</div></div>`;
 if(S.me.role==='teacher'){
  const ordered=nodesInOrder(S.folders.map(f=>({...f,parent:f.parent_id}))),path=id=>{const names=[],seen=new Set();while(id&&!seen.has(id)){seen.add(id);const f=S.folders.find(x=>x.id===id);if(!f)break;names.unshift(f.name);id=f.parent_id;}return names.join(' / ');};
  html+=`<div class="folder-bar">${!S.trash?`<button class="folder-pill ${!S.folder?'active':''}" data-action="folder-filter" data-id="">全部工程</button><button class="folder-pill ${S.folder==='root'?'active':''}" data-action="folder-filter" data-id="root">根目录</button>`:''}${ordered.filter(f=>f.trashed===S.trash).map(f=>`<div class="row"><button class="folder-pill ${S.folder===f.id?'active':''}" data-action="${S.trash?'restore-folder':'folder-filter'}" data-id="${f.id}" title="${esc(path(f.id))}">${icon('folder')}${esc(path(f.id))}${S.trash?'（恢复）':''}</button>${!S.trash?`<button class="icon-btn" data-action="edit-folder" data-id="${f.id}" aria-label="管理文件夹 ${esc(f.name)}">${icon('dots')}</button>`:''}</div>`).join('')}</div>`;
 }

 html+=items.length?`<div class="grid3" id="project-list">${items.map(x=>`<article class="card project-card" data-record-id="${x.id}" data-search="${esc(x.title+' '+x.meta.year+' '+x.meta.class_name)}"><div class="row between"><div class="project-icon">${icon('folder')}</div>${tag(stageNames[x.state]||x.state,x.state==='publication'?'':'gray')}</div><h3>${S.trash?esc(x.title):`<a href="#/project/${x.id}/${x.can_review?'overview':'submission'}">${esc(x.title)}</a>`}</h3><div class="project-meta">${esc(x.meta.year)} · ${esc(x.meta.class_name)}<br>${x.can_review?x.student_count+' 位参评学生 · ':''}${x.evidence_count} 份个人材料<br>更新于 ${fmt(x.updated_at)}</div><div class="bottom">${S.trash?btn('restore-project','恢复工程','secondary mini',{id:x.id,revision:x.revision},'refresh'):link(x.can_review?'进入工程':'上传 / 查看','#/project/'+x.id+'/'+(x.can_review?'overview':'submission'),'btn ghost mini','arrow')}${x.can_manage?btn('project-menu','管理','ghost mini',{id:x.id},'dots'):''}</div></article>`).join('')}</div>`:empty(S.trash?'回收站为空':'还没有可见工程',S.me.role==='student'?'负责教师创建工程并将你加入名单后，会在这里出现。':'新建工程，或导入已有的 .zcp 工程文件。');
 shell(html,'workspace','工作空间');
}
A['toggle-trash']=async()=>{S.trash=!S.trash;S.folder=null;await workspace();};
A['folder-filter']=async b=>{S.folder=b.dataset.id||null;await workspace();};
A['new-folder']=()=>folderDialog();
A['restore-folder']=async b=>{const f=S.folders.find(x=>x.id===b.dataset.id);await api('/api/folders/'+f.id,{method:'PATCH',body:{name:f.name,parent_id:null,trashed:false}});toast('文件夹已恢复到根目录。');await workspace();};
A['edit-folder']=b=>folderDialog(S.folders.find(x=>x.id===b.dataset.id));
function folderDialog(f){modal(f?'管理文件夹':'新建文件夹',`<form data-form="folder" data-id="${f?.id||''}">${field('name','文件夹名称',f?.name||'','','required')}${select('parent_id','上级目录',[['','根目录'],...S.folders.filter(x=>!x.trashed&&x.id!==f?.id).map(x=>[x.id,x.name])],f?.parent_id||(S.folder==='root'?'':S.folder)||'')}${f?`<label class="checkbox"><input type="checkbox" name="trashed" ${f.trashed?'checked':''}>移入回收站（目录必须为空）</label>`:''}${actions()}</form>`);}
F.folder=async(form)=>{const d=formData(form);await api('/api/folders'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PATCH':'POST',body:{name:d.name,parent_id:d.parent_id||null,trashed:!!d.trashed}});A.close();toast('目录已更新。');await workspace();};
A['new-project']=async()=>{S.students=await allStudents();const y=new Date().getFullYear()-(new Date().getMonth()<8?1:0);modal('新建综测工程',`<form data-form="new-project"><div class="field-grid">${field('title','工程名称',`${y-1}—${y} 学年综合测评`,'text','required')}${field('year','参评学年',`${y-1}-${y}`,'text','required')}${field('class_name','班级名称','','text','required')}${field('responsible','负责人',S.me.name)}${field('assessment_start','成果有效期起',`${y-1}-09-01`,'date','required')}${field('assessment_end','成果有效期止',`${y}-08-31`,'date','required')}</div><label class="checkbox" style="margin-top:15px"><input type="checkbox" name="test_only">这是测试工程，不作为正式测评依据</label><hr><h3>选择参评学生</h3><div class="row">${search('new-members','搜索班级、姓名或学号')}${btn('check-all','选中当前可见','secondary mini',{target:'new-members'})}</div><div class="check-list" id="new-members" style="margin-top:10px">${studentChecks(S.students,[])}</div><p class="small muted" style="margin-top:12px">名单中没有学生？先到“学生名册”导入学生名册。</p>${actions('建立工程')}</form>`,true);};
function studentChecks(students,selected,name='student_ids'){return students.map(s=>`<label class="check-item" data-search="${esc(s.name+' '+s.number+' '+s.class_name)}"><input type="checkbox" name="${name}" value="${s.id}" ${selected.includes(s.id)?'checked':''}><div><strong>${esc(s.name)}</strong><div class="sub">${esc(s.number)} · ${esc(s.class_name)}</div></div></label>`).join('');}
F['new-project']=async(form)=>{const d=formData(form);d.student_ids=new FormData(form).getAll('student_ids');d.test_only=!!d.test_only;d.folder_id=S.folder==='root'?null:S.folder;const p=await api('/api/projects',{method:'POST',body:d});A.close();location.hash='#/project/'+p.id+'/setup';};
A['import-project']=()=>modal('导入工程文件',`<form data-form="import-project">${field('file','选择 .zcp 工程文件','','file','accept=".zcp" required')}<div class="callout amber">将校验所有文件的 SHA-256。不会导入登录账号权限，也不会自动开放旧公示。相同学号会匹配现有学生；姓名冲突将拒绝导入。</div>${actions('校验并导入')}</form>`);
F['import-project']=async form=>{const data=new FormData();data.append('file',form.elements.file.files[0]);const r=await api('/api/projects-import',{method:'POST',body:data,raw:true});A.close();location.hash='#/project/'+r.project.id+'/archive';if(r.credentials.length)credentialsModal(r.credentials);else toast('工程已导入，发布前请完成来源核对。');};
A['project-menu']=b=>{const p=S.projects.find(x=>x.id===b.dataset.id)||S.project;S.fileProject=p;modal('管理工程',`<p><strong>${esc(p.title)}</strong></p><div class="row wrap">${btn('file-rename','重命名','secondary',{},'edit')}${btn('file-move','移动','secondary',{},'folder')}${btn('file-copy','创建副本','secondary',{},'copy')}${btn('file-trash','移入回收站','danger',{},'trash')}</div><p class="small muted" style="margin-top:18px">副本不继承公示可见性或审核权限。回收站不会物理删除原始材料和审计历史。</p>`);};
A['file-rename']=()=>modal('重命名工程',`<form data-form="file-action" data-kind="rename">${field('title','名称',S.fileProject.title,'text','required')}${actions()}</form>`);
A['file-copy']=()=>modal('创建工程副本',`<form data-form="file-action" data-kind="copy">${field('title','副本名称',S.fileProject.title+'（副本）','text','required')}<p class="muted small">文件资源仍按内容哈希去重，不会重复保存字节。</p>${actions('创建副本')}</form>`);
A['file-move']=async()=>{S.folders=await api('/api/folders');modal('移动工程',`<form data-form="file-action" data-kind="move">${select('folder_id','目标文件夹',[['','根目录'],...S.folders.filter(f=>!f.trashed).map(f=>[f.id,f.name])],S.fileProject.folder_id||'')}${actions('移动')}</form>`);};
A['file-trash']=()=>modal('确认移入回收站',`<form data-form="file-action" data-kind="trash"><p>工程将从普通工作空间隐藏。材料不会被删除，可从回收站恢复。</p>${actions('确认回收')}</form>`);
F['file-action']=async form=>{const d=formData(form),action=form.dataset.kind;await api('/api/projects/'+S.fileProject.id+'/file-action',{method:'POST',body:{revision:S.fileProject.revision,action,title:d.title||null,folder_id:d.folder_id||null}});A.close();toast('工程管理操作已保存。');location.hash='#/workspace';await workspace();};
A['restore-project']=async b=>{await api('/api/projects/'+b.dataset.id+'/file-action',{method:'POST',body:{revision:+b.dataset.revision,action:'restore'}});toast('工程已恢复到根目录。');await workspace();};
/* ---------------- Project: preparation and chronological navigation -------- */
function latestRules(){return S.project.body.rule_versions.at(-1);}
function latestPrompt(){return S.project.body.instruction_versions.at(-1);}
function nodesInOrder(nodes){const map=new Map(nodes.map(n=>[n.id,n])),children=new Map();nodes.forEach(n=>{const k=n.parent||'';if(!children.has(k))children.set(k,[]);children.get(k).push(n);});const stack=(children.get('')||[]).map(n=>[n,0]).reverse(),out=[],seen=new Set();while(stack.length){const [n,depth]=stack.pop();if(seen.has(n.id))continue;seen.add(n.id);out.push({...n,depth});(children.get(n.id)||[]).slice().reverse().forEach(c=>stack.push([c,depth+1]));}nodes.filter(n=>!seen.has(n.id)).forEach(n=>out.push({...n,depth:0}));return out;}
function nodePath(id,nodes=latestRules().nodes){const map=new Map(nodes.map(n=>[n.id,n])),parts=[],seen=new Set();while(id&&map.has(id)&&!seen.has(id)){seen.add(id);const n=map.get(id);parts.unshift(n.name);id=n.parent;}return parts.join(' / ');}
function leafOptions(nodes=latestRules().nodes){const parents=new Set(nodes.map(n=>n.parent));return nodesInOrder(nodes).filter(n=>!parents.has(n.id)).map(n=>[n.id,nodePath(n.id,nodes)]);}
function studentById(id){return S.project?.body?.roster?.find(s=>s.id===id)||S.students.find(s=>s.id===id)||{name:'本人',number:'',class_name:''};}
async function projectOverview(){const p=S.project,b=p.body,valid=b.evidence.filter(e=>e.annotations.at(-1)?.data.status==='valid').length,pending=b.evidence.filter(e=>!e.annotations.length||e.annotations.at(-1).data.status!=='valid').length;paintProject('overview',`<div class="grid4"><div class="card stat"><div class="small">参评学生</div><div class="number">${b.roster.length}</div><div class="small">由负责教师统一管理</div></div><div class="card stat"><div class="small">个人材料</div><div class="number">${b.evidence.length}</div><div class="small">原始图片不可覆盖</div></div><div class="card stat"><div class="small">已认定有效</div><div class="number">${valid}</div><div class="small">是否最终计入由规则决定</div></div><div class="card stat"><div class="small">待处理 / 非有效</div><div class="number">${pending}</div><div class="small">请进入材料标注页面处理</div></div></div><div class="grid2" style="margin-top:22px"><section class="card"><div class="card-title"><h2>操作步骤</h2>${tag('流程导航','gray')}</div><div class="workflow">${steps.slice(1).map(([key,label],i)=>`<a class="workflow-card" href="${purl(key)}"><div class="circle">${i}</div><div><h3>${label}</h3><p>${['名册、规则树、源文件与时间','手机上传，自动收据，查看缺交','图片与表单并排，只做局部判断','名单类奖项一份维护，课程自动计算','查看原始分、封顶与完整轨迹','个人可见，增量补充，申请留痕','导出单工程文件与只读材料包'][i]}</p></div></a>`).join('')}</div></section><div class="stack"><section class="card"><div class="card-title"><h2>时间窗口</h2>${icon('clock')}</div>${timeLine('开始提交',b.schedule?.opens_at)}${timeLine('截止提交',b.schedule?.deadline_at)}${timeLine('公示申诉截止',b.schedule?.appeal_deadline)}<div class="callout" style="margin-top:15px">服务端使用带时区的时刻控制入口。超过截止时间，不接受私聊补传；需通过系统申请。</div></section><section class="card"><h2>工程记录</h2><p class="muted small">当前修订 r${p.revision}。规则 ${b.rule_versions.length} 个版本，公示 ${b.snapshots.length} 个快照，名单类奖项 ${b.public_bindings.length} 份冻结引用。</p><p class="small muted">结果“结构合法”和“材料真实有效”是不同的问题。系统防止非法计算与越权，争议事实仍由学院认定。</p>${link('查看材料标注',purl('review'),'btn secondary','arrow')}</section></div></div>`);}
function timeLine(label,t){return `<div class="row between" style="padding:12px 0;border-bottom:1px solid var(--line)"><span class="muted small">${label}</span><strong class="small">${fmt(t)}</strong></div>`;}
function setupView(){const p=S.project,b=p.body,manage=p.can_manage;
 if(!S.dirtyRules||!S.ruleDraft)S.ruleDraft=structuredClone(latestRules().nodes);
 const now=new Date(),defaults={opens_at:new Date(now.getTime()+3600000).toISOString(),deadline_at:new Date(now.getTime()+7*86400000).toISOString(),appeal_deadline:new Date(now.getTime()+12*86400000).toISOString()},schedule=b.schedule||defaults;
 const tree=nodesInOrder(S.ruleDraft).map(n=>`<div class="rule-row" style="padding-left:${Math.min(n.depth,10)*15+5}px"><span class="branch">${n.parent?'└':'◈'}</span><div class="rule-name">${esc(n.name)}<span class="rule-id">${esc(n.id)}</span></div><div class="rule-tags">${tag(n.aggregate==='max'?'取最高':'可累加','gray')}${n.cap!==null?tag('上限 '+n.cap,'gray'):''}${n.weight!=='1'?tag('× '+n.weight,''):''}${n.required?tag('必需','amber'):''}${manage?`<button class="icon-btn" data-action="rule-edit" data-id="${esc(n.id)}" aria-label="编辑 ${esc(n.name)}">${icon('edit')}</button><button class="icon-btn" data-action="rule-add" data-parent="${esc(n.id)}" aria-label="添加子分类">${icon('plus')}</button>`:''}</div></div>`).join('');
 paintProject('setup',`<div class="split-config"><section class="card"><div class="card-title"><div><h2>分类与聚合规则</h2><div class="small muted">任意层级 · 每一级独立设置上限与取最高</div></div>${projectTable('rules','导出分类规则')}${manage?btn('rules-json','高级导入','secondary mini',{},'code'):''}</div>${S.dirtyRules?'<div class="callout amber">当前为未保存草稿。保存新规则版本后才会参与计算。</div>':''}<div>${tree}</div>${manage?`<div class="form-actions">${btn('rules-reset','放弃草稿','ghost')}${btn('rules-save','保存新规则版本','',{},'check')}</div>`:''}<p class="small muted" style="margin-top:17px">计算时应用上限，材料的原始分值保留不变。仅叶子分类接受计分输入。</p></section><div class="stack"><section class="card"><div class="card-title"><h2>参评名单与审核权限</h2>${projectTable('students','导出参评名单')}${manage?btn('members','管理名单','secondary mini',{},'users'):''}</div><div class="row between"><span class="small muted">参评学生</span><strong>${b.student_ids.length} 人</strong></div><div class="row between" style="margin-top:14px"><span class="small muted">授权交叉审核人员</span><strong>${b.reviewer_ids.length} 人</strong></div><p class="small muted" style="margin-top:14px">学委权限按工程授予，可授权不同年级同学交叉核验。审核人不能给自己的材料标注。</p></section><section class="card"><div class="card-title"><h2>开放与截止时间</h2>${tag('服务端强制执行','gray')}</div><form data-form="schedule"><div class="field-grid">${field('opens_at','开放提交',localDate(schedule.opens_at),'datetime-local',manage?'required':'disabled')}${field('deadline_at','截止提交',localDate(schedule.deadline_at),'datetime-local',manage?'required':'disabled')}<div class="span2">${field('appeal_deadline','公示申诉截止',localDate(schedule.appeal_deadline),'datetime-local',manage?'required':'disabled')}</div></div><p class="small muted" style="margin-top:12px">当前显示时区：${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}。开放后只能延长提交窗口，不能缩短。</p>${manage?'<button type="submit" class="btn secondary full">保存时间窗口</button>':''}</form></section><section class="card"><div class="card-title"><h2>细则与公共源文件</h2>${manage?btn('document-upload','上传文件','secondary mini',{},'upload'):''}</div>${b.source_documents.length?b.source_documents.map(d=>`<div class="document">${icon('file')}<div class="grow"><a class="name" href="/api/resources/${d.sha256}" target="_blank" rel="noopener">${esc(d.name)}</a><div><small>${d.purpose==='rules'?'评分细则':'佐证文件'} · ${size(d.size)} · SHA256 ${d.sha256.slice(0,12)}…</small></div></div></div>`).join(''):'<p class="muted small">尚未上传细则。支持多个 PDF 作为同一工程的规则来源。</p>'}<p class="small muted" style="margin-top:15px">系统只存储这些文件，不读取或执行其中的文字。外部 Agent 可以通过授权接口获取。</p></section><section class="card"><div class="card-title"><h2>学院解释与 Agent 辅助说明</h2>${tag((b.instruction_versions.length||0)+' 个版本','gray')}</div><form data-form="instructions">${area('text','补充细则未明确、已经由学院确认的解释',latestPrompt()?.text||'',manage?'rows="7"':'readonly rows="7"')}${manage?`${field('reason','本次补充的依据/原因','','text','required')}<div class="form-actions"><button type="submit" class="btn secondary">保存新解释版本</button></div>`:''}</form></section>${manage&&b.state==='setup'?`<section class="card"><h2>准备完成后，启用提交阶段</h2><p class="small muted">时间尚未到达时，系统会显示“等待开放”；到达预定时刻后入口自动允许提交。</p>${btn('transition','启用提交阶段','full',{state:'submission'},'arrow')}</section>`:''}</div></div>`);
}
A['rules-reset']=()=>{S.dirtyRules=false;setupView();};
A['rule-edit']=b=>ruleDialog(S.ruleDraft.find(n=>n.id===b.dataset.id));
A['rule-add']=b=>ruleDialog(null,b.dataset.parent);
function ruleDialog(node,parent){const newNode=!node,n=node||{id:'category.'+crypto.randomUUID().slice(0,8),parent:parent||S.ruleDraft[0].id,name:'',aggregate:'sum',cap:null,floor:null,weight:'1',negative_policy:'signed',required:false,source:''};S.editNode=n.id;modal(newNode?'添加子分类':'编辑分类规则',`<form data-form="rule-node" data-new="${newNode}"><div class="field-grid">${field('name','分类名称',n.name,'text','required')}${field('id','稳定分类ID',n.id,'text',newNode?'required':'readonly')}${select('parent','父分类',[['','根节点'],...nodesInOrder(S.ruleDraft).filter(x=>x.id!==n.id).map(x=>[x.id,'　'.repeat(Math.min(x.depth,5))+x.name])],n.parent||'')}${select('aggregate','同级输入处理',[['sum','可累加：求和'],['max','不可叠加：取最高']],n.aggregate)}${field('cap','上限（空表示不设限）',n.cap??'','text','inputmode="decimal"')}${field('floor','下限（空表示不设限）',n.floor??'','text','inputmode="decimal"')}${field('weight','本节点权重',n.weight,'text','required inputmode="decimal"')}${select('negative_policy','扣分与封顶的顺序',[['signed','带符号聚合 → 权重 → 上下限'],['separate','正向聚合封顶后，再加独立负分']],n.negative_policy)}<div class="span2">${area('source','细则条款/学院解释出处',n.source)}</div></div><label class="checkbox" style="margin-top:14px"><input type="checkbox" name="required" ${n.required?'checked':''}>本分类缺少输入时，不得认定完整成绩</label><div class="form-actions">${!newNode&&n.parent?btn('rule-delete','移除此叶子分类','danger',{id:n.id}):''}${btn('close','取消','secondary')}<button type="submit" class="btn">保存到规则草稿</button></div></form>`,true);}
F['rule-node']=async form=>{const d=formData(form),node={id:d.id,parent:d.parent||null,name:d.name,aggregate:d.aggregate,cap:d.cap||null,floor:d.floor||null,weight:d.weight,negative_policy:d.negative_policy,required:!!d.required,source:d.source};if(form.dataset.new==='true')S.ruleDraft.push(node);else S.ruleDraft=S.ruleDraft.map(n=>n.id===S.editNode?node:n);S.dirtyRules=true;A.close();setupView();};
A['rule-delete']=b=>{if(S.ruleDraft.some(x=>x.parent===b.dataset.id)){toast('请先处理子分类，不能直接移除非叶子节点。',true);return;}S.ruleDraft=S.ruleDraft.filter(x=>x.id!==b.dataset.id);S.dirtyRules=true;A.close();setupView();};
A['rules-save']=()=>modal('保存新的规则版本',`<form data-form="rules-save">${area('reason','本次修改的原因','','required')}<div class="callout amber">只改上限或聚合方式时会直接重算。改变分类含义或层级时，旧局部标注将提示需要重新确认。已有公示快照保持不变。</div>${actions('校验并保存新版本')}</form>`);
F['rules-save']=async form=>{const d=formData(form);await updateProject('/api/projects/'+pid()+'/rules','PUT',{revision:S.project.revision,reason:d.reason,rules:{nodes:S.ruleDraft,display_places:latestRules().display_places,explanation:latestRules().explanation}});S.dirtyRules=false;A.close();toast('规则树已校验，并生成新版本。');setupView();};
A['rules-json']=()=>modal('高级规则导入',`<form data-form="rules-json">${area('json','粘贴 nodes 数组或完整规则 JSON',JSON.stringify(S.ruleDraft,null,2),'class="mono" required')}<p class="small muted">这是可选的批量编辑入口。一般调整可直接使用每个分类右侧的编辑按钮。</p>${actions('加载到草稿')}</form>`,true);
F['rules-json']=async form=>{const data=JSON.parse(form.elements.json.value);S.ruleDraft=Array.isArray(data)?data:data.nodes;if(!Array.isArray(S.ruleDraft))throw new Error('必须提供 nodes 数组。');S.dirtyRules=true;A.close();setupView();};
F.schedule=async form=>{const d=formData(form);await updateProject('/api/projects/'+pid()+'/schedule','PUT',{revision:S.project.revision,opens_at:new Date(d.opens_at).toISOString(),deadline_at:new Date(d.deadline_at).toISOString(),appeal_deadline:new Date(d.appeal_deadline).toISOString()});toast('开放与截止时间已保存。');setupView();};
F.instructions=async form=>{const d=formData(form);await updateProject('/api/projects/'+pid()+'/instructions','PUT',{revision:S.project.revision,...d});toast('辅助说明已唯一存档为新版本。');setupView();};
A['document-upload']=()=>modal('上传规则或佐证文件',`<form data-form="document-upload">${select('purpose','文件用途',[['rules','评分细则 PDF（可多文件）'],['support','名单类奖项 / 其他佐证源文件']])}${field('files','选择文件','','file','multiple required accept=".pdf,.docx,.xlsx,image/jpeg,image/png,image/webp,image/heic"')}<div class="callout">原始文件按内容哈希存储一次。系统不会执行文件中的任何文本或指令。</div>${actions('上传并存档')}</form>`);
F['document-upload']=async form=>{for(const file of form.elements.files.files){const fd=new FormData();fd.append('file',file);fd.append('purpose',form.elements.purpose.value);fd.append('revision',S.project.revision);S.project=await api('/api/projects/'+pid()+'/documents',{method:'POST',body:fd,raw:true});}A.close();toast('文件已存档。');setupView();};
A.members=async()=>{[S.students,S.staff]=await Promise.all([allStudents(),api('/api/staff-options')]);modal('参评学生与交叉审核人员',`<form data-form="members"><div class="grid2"><div><h3>参评学生</h3>${search('member-list')}<div class="check-list" id="member-list" style="margin-top:10px">${studentChecks(S.students,S.project.body.student_ids)}</div></div><div><h3>授权审核人员（可跨年级）</h3>${search('staff-list','搜索审核人员')}<div class="check-list" id="staff-list" style="margin-top:10px">${S.staff.filter(a=>a.id!==S.me.id).map(a=>`<label class="check-item" data-search="${esc(a.name)}"><input type="checkbox" name="reviewer_ids" value="${a.id}" ${S.project.body.reviewer_ids.includes(a.id)?'checked':''}><div><strong>${esc(a.name)}</strong><div class="sub">${a.role==='teacher'?'教师':'学生 · 授权后为本工程学委/审核员'}</div></div></label>`).join('')}</div></div></div><div class="callout" style="margin-top:15px">授权审核只作用于此工程。学生审核员不能评分自己的材料，不能管理规则、时间、公示和他人的账号。</div>${actions('保存名单与权限')}</form>`,true);};
F.members=async form=>{const d=new FormData(form);await updateProject('/api/projects/'+pid()+'/members','PUT',{revision:S.project.revision,student_ids:d.getAll('student_ids'),reviewer_ids:d.getAll('reviewer_ids')});A.close();toast('名单与权限已保存。');setupView();};
A.transition=b=>modal('切换工程阶段',`<form data-form="transition" data-state="${b.dataset.state}">${area('reason','操作原因','','required')}<div class="callout amber">阶段切换会校验截止时间和资料完备性，不能跳过已通知的提交或公示窗口。</div>${actions('确认切换')}</form>`);
F.transition=async form=>{await updateProject('/api/projects/'+pid()+'/transition','POST',{revision:S.project.revision,state:form.dataset.state,reason:form.elements.reason.value});A.close();toast('阶段已更新。');location.hash=purl('overview');await projectOverview();};

async function studentsView(){S.students=await allStudents();shell(heading('学生名册','学生账号只能由教师导入创建；学委权限按工程独立授权。',templateLink('students')+link('导出名册','/api/students/export','btn secondary','download')+btn('roster-import','导入学生','',{},'plus'))+`<section class="card"><div class="card-head"><div><h2>学院学生名册 <span class="muted">${S.students.length}</span></h2><p>学号是身份键。更新相同学号不会重复创建账号。</p></div>${search('student-table')}</div><div class="table-wrap"><table><thead><tr><th>姓名</th><th>学号</th><th>班级</th><th>登录账号</th><th>状态</th><th>操作</th></tr></thead><tbody id="student-table">${S.students.map(s=>`<tr data-record-id="${s.id}" data-search="${esc(s.name+' '+s.number+' '+s.class_name)}"><td><strong>${esc(s.name)}</strong></td><td class="mono">${esc(s.number)}</td><td>${esc(s.class_name)}</td><td class="mono">${esc(s.username)}</td><td>${tag(s.disabled?'已停用':'正常',s.disabled?'red':'')}</td><td>${btn('student-edit','编辑','ghost small-btn',{id:s.id})}${btn('reset-password','重置密码','ghost small-btn',{id:s.account_id,name:s.name})}</td></tr>`).join('')}</tbody></table></div></section><div class="callout" style="margin-top:20px">需要指定学委或跨年级审核员时，进入相应工程 → 准备工程 → 名单与权限。审核员不能审核自己的材料。</div>`,'students','学生管理');}
A['student-edit']=b=>{const s=S.students.find(x=>x.id===b.dataset.id);S.editStudent=structuredClone(s);modal('编辑学生资料',`<form data-form="student-edit">${field('number','学号（不可修改）',s.number,'text','readonly')}${field('name','姓名',s.name,'text','required')}${field('class_name','班级',s.class_name,'text','required')}<label class="checkbox"><input type="checkbox" name="disabled" ${s.disabled?'checked':''}>停用该学生的登录账号</label><p class="small muted">修改不会删除原始材料，也不会改写已有公示快照中的身份资料。停用后现有登录会话立即失效。</p>${actions('保存学生资料')}</form>`);};
F['student-edit']=async form=>{const d=formData(form),old=S.editStudent;await api('/api/students/'+old.id,{method:'PATCH',body:{name:d.name,class_name:d.class_name,disabled:!!d.disabled,expected_name:old.name,expected_class_name:old.class_name,expected_disabled:old.disabled}});A.close();toast('学生资料已保存。');await studentsView();};
A['roster-import']=()=>modal('导入学生名册',`<form data-form="roster-import"><div class="callout">上传 UTF-8 CSV 或 XLSX，第一行表头必须包含「学号、姓名、班级」。学号请使用文本格式。导入后一次性提供初始密码，新账号首次登录必须修改密码。</div>${templateLink('students')}${field('file','选择名册','','file','accept=".csv,.xlsx"')}<details><summary>也可以直接新增一名学生</summary><div class="field-grid">${field('number','学号')}${field('name','姓名')}${field('class_name','班级')}</div></details>${actions('校验并导入')}</form>`);
A['reset-password']=b=>modal('重置登录密码',`<p>重置「${esc(b.dataset.name)}」的密码将撤销其现有会话和服务令牌。</p><form data-form="reset-password" data-id="${esc(b.dataset.id)}">${actions('生成新初始密码')}</form>`);
F['reset-password']=async form=>{const r=await api('/api/accounts/'+form.dataset.id+'/reset-password',{method:'POST'});credentialsModal([r]);};

function ownEvidence(){return S.project.body.evidence.filter(e=>e.student_id===S.me.student_id);}
function evidenceImage(id,original=false){return '/api/projects/'+pid()+'/evidence/'+encodeURIComponent(id)+'/image'+(original?'?original=true':'');}
function submissionOpen(){const p=S.project,s=p.body.schedule;if(!s||p.body.meta?.import_unverified)return false;const t=Date.now();return (['submission','scheduled'].includes(p.state)&&t>=Date.parse(s.opens_at)&&t<Date.parse(s.deadline_at))||(p.state==='publication'&&t<Date.parse(s.appeal_deadline))||(p.body.appeals||[]).some(a=>a.student_id===S.me.student_id&&a.history?.at(-1)?.decision==='approved'&&Date.parse(a.history.at(-1).until)>t&&a.history.at(-1).created_at>=(p.body.meta.workflow_restart_at||''));}
async function submissionView(){
 const p=S.project,b=p.body;if(S.me.role!=='student'||(p.can_review&&!b.student_ids?.includes(S.me.student_id)))return submissionMonitor();
 const grant=(b.appeals||[]).find(a=>a.student_id===S.me.student_id&&a.history?.at(-1)?.decision==='approved'&&Date.parse(a.history.at(-1).until)>Date.now()&&a.history.at(-1).created_at>=(b.meta.workflow_restart_at||''));if(grant&&!S.requestId)S.requestId=grant.id;const open=submissionOpen(),ev=ownEvidence(),queue=S.files.filter(f=>f.project===p.id),last=b.receipts?.filter(r=>r.student_id===S.me.student_id).at(-1);
 paintProject('submission',`<div class="student-top"><div><div class="eyebrow">材料提交说明</div><h2>${open?'请选择并提交证明图片':'当前提交窗口未开放'}</h2><p class="muted">一张图片表达一个成果。同一成果有多张证明时可一并提交，由审核人员关联，不会重复加分。</p></div>${tag(open?'可提交':'已锁定',open?'':'gray')}</div>${p.state==='publication'?'<div class="callout amber">公示期间补交只增加新材料。旧材料不会被覆盖或删除，审核确认替代关系后才会改变计算。</div>':''}<section class="card pad" id="evidence-paste-area" tabindex="0" style="margin-top:20px"><div class="row between wrap"><div><h3>选择证明图片</h3><p class="small muted">JPEG、PNG、WebP、HEIC；每张最多 20 MB。多成果拼图请分别截取后上传。</p></div><div class="row wrap">${open?btn('capture-evidence','截屏','secondary desktop-capture',{},'camera'):''}<label class="btn secondary ${open?'':'disabled'}">${icon('camera')}拍照<input class="visually-hidden" type="file" data-upload="evidence" accept="image/*" capture="environment" ${open?'':'disabled'}></label><label class="btn ${open?'':'disabled'}">${icon('image')}从相册选择<input class="visually-hidden" type="file" data-upload="evidence" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" multiple ${open?'':'disabled'}></label></div></div><div class="upload-grid" id="upload-queue">${queue.map(f=>`<div class="upload-item" data-record-id="${f.key}"><img src="${f.url}" alt="待提交图片预览"><div class="upload-item-info"><span>${esc(f.state==='done'?'已接收':f.state==='error'?f.error:f.file.name)}</span>${f.state==='done'?tag('已接收'):btn('remove-file','移除','ghost small-btn',{key:f.key})}</div></div>`).join('')}</div>${!queue.length?'<div class="upload-drop" data-drop="evidence">'+icon('upload')+'<strong>将证明图片拖至此处，或使用上方按钮选择图片</strong><span>电脑上可使用“截屏”，或按系统截图快捷键后在此按 Ctrl+V / ⌘V 粘贴</span></div>':''}<div class="row between wrap"><p class="small muted">${queue.length?queue.length+' 张待办图片':'上传后立即保存原件'} · 截止 ${fmt(p.state==='publication'?b.schedule?.appeal_deadline:b.schedule?.deadline_at)}</p><div class="row wrap">${open?btn('upload-all',S.uploading?'正在上传…':'提交选中的图片','',{},'upload'):''}${open?btn('receipt','确认本轮提交完成','secondary',{},'check'):''}</div></div><p class="small muted">${last?'最近回执：'+fmt(last.created_at)+' · 包含 '+last.evidence_ids.length+' 张图片':'尚未确认提交完成；已上传的图片已经保存。没有材料也可以确认完成。'}</p></section><section class="card" style="margin-top:20px"><div class="card-head"><div><h2>已保存的原始材料 <span class="muted">${ev.length}</span></h2><p>只有公示后才能看到认定结果。这里始终保留原始提交记录。</p></div>${!open&&['review','publication'].includes(p.state)?btn('appeal','申请补交','secondary'):''}</div><div class="pad"><div class="upload-grid">${ev.map(e=>`<div class="upload-item"><a href="${evidenceImage(e.id,true)}" target="_blank" rel="noopener"><img loading="lazy" src="${evidenceImage(e.id)}" alt="已提交材料"></a><div class="upload-item-info"><div><strong>${fmt(e.submitted_at)}</strong><span>${e.parent_id?'增量补充材料':'原始提交'} · ${esc(e.resource_sha.slice(0,10))}</span></div></div></div>`).join('')||'<p class="muted">还没有上传材料。</p>'}</div></div></section>`);
}
function submissionMonitor(){const p=S.project,b=p.body;paintProject('submission',`<div class="section-heading"><div><h2>收件进度</h2><p>以服务器保存记录为准；未确认不等于图片未接收。</p></div><div class="row wrap">${projectTable('submissions','导出收件进度')}${search('submission-table')}${S.me.role==='teacher'?btn('transition','截止后进入标注','secondary',{state:'review'},'arrow'):''}</div></div><section class="card"><div class="table-wrap"><table><thead><tr><th>学生</th><th>学号</th><th>材料数</th><th>提交确认</th><th>最近提交</th></tr></thead><tbody id="submission-table">${p.body.roster.map(s=>{const ev=b.evidence.filter(e=>e.student_id===s.id),r=b.receipts.filter(r=>r.student_id===s.id).at(-1);return `<tr data-search="${esc(s.name+' '+s.number+' '+(r?'已确认':'未确认'))}"><td>${esc(s.name)}</td><td class="mono">${esc(s.number)}</td><td>${ev.length}</td><td>${tag(r?'已确认':'未确认',r?'':'amber')}</td><td>${ev.length?fmt(ev.at(-1).submitted_at):'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`);}
async function addFiles(fileList){if(!submissionOpen()){toast('当前不在允许提交的时间窗口。',true);return;}for(const file of fileList){if(file.size>20*1048576){toast(file.name+' 超过20 MB，未加入。',true);continue;}if(!/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name)&&!file.type.startsWith('image/')){toast('只能选择图片。',true);continue;}S.files.push({file,key:crypto.randomUUID(),project:pid(),url:URL.createObjectURL(file),state:'new'});}await submissionView();}
A['remove-file']=b=>{const f=S.files.find(f=>f.key===b.dataset.key);if(f){URL.revokeObjectURL(f.url);S.files=S.files.filter(x=>x!==f);}submissionView();};
A['upload-all']=async()=>{if(S.uploading)return;S.uploading=true;await submissionView();try{for(const f of S.files.filter(f=>f.project===pid()&&f.state!=='done')){const fd=new FormData();fd.append('file',f.file);fd.append('idempotency_key',f.key);if(S.supplementFor)fd.append('parent_id',S.supplementFor);if(S.requestId)fd.append('request_id',S.requestId);try{await api('/api/projects/'+pid()+'/evidence',{method:'POST',body:fd,raw:true});f.state='done';}catch(e){f.state='error';f.error=e.message;toast(e.message,true);}}await loadProject(pid());toast('本轮上传已处理。请检查接收状态；失败的图片可点击“提交选中的图片”重试。');}finally{S.uploading=false;await submissionView();}};
A.receipt=async()=>{const r=await api('/api/projects/'+pid()+'/receipt',{method:'POST'});await loadProject(pid());await submissionView();modal('提交回执',`<div class="score-hero"><div>${icon('check')}</div><h2>系统已保存本轮确认</h2><p>${fmt(r.created_at)} · ${r.evidence_ids.length} 张材料</p><code>${esc(r.id)}</code></div><div class="callout">回执确认已收到的图片，不代表材料已经认定有效。</div>`);};

// Export links are read-only; unsaved form drafts are never silently included.
function projectTable(kind,label){return S.me.role==='teacher'?link(label,'/api/projects/'+pid()+'/export/table/'+kind,'btn secondary small-btn','download'):'';}
function templateLink(kind,project=null){return link('下载导入模板','/api/export-templates/'+kind+(project?'?pid='+encodeURIComponent(project):''),'btn secondary small-btn','download');}
function stampFields(record={},inherit=false){return select('has_stamp','是否有盖章',[['',inherit?'未单独填写（使用来源记录）':'未判定'],['true','是'],['false','否']],record.has_stamp===true?'true':record.has_stamp===false?'false':'')+area('stamp_text','盖章上的文字',record.stamp_text||'','placeholder="仅按可见文字记录；模糊部分说明无法识读，不推测"');}
function stampValue(value){const s=String(value??'').trim().toLowerCase();if(['','未判定','未知','null'].includes(s))return null;if(['是','true','1'].includes(s))return true;if(['否','false','0'].includes(s))return false;throw new Error('是否有盖章只能填写是、否或未判定。');}
function stampData(d){const result={has_stamp:stampValue(d.has_stamp),stamp_text:d.stamp_text?.trim()||null};if(result.stamp_text&&result.has_stamp!==true)throw new Error('填写盖章文字前，请将是否有盖章设为“是”。');return result;}
A['export-tables']=()=>modal('导出工程表格',`<p>以下文件均导出已保存的数据。未保存的页面草稿不在导出范围内。</p><div class="export-link-grid">${link('全部分类多级总表','/api/projects/'+pid()+'/export/xlsx','btn secondary','download')}${[['achievements','全部成果明细'],['students','参评学生名单'],['rules','分类规则'],['submissions','收件进度'],['public','本工程名单类奖项'],['academic','已保存课程成绩'],['appeals','补交与异议申请'],['publications','公示版本目录'],['audit','工程审计日志']].map(([kind,label])=>projectTable(kind,label)).join('')}${btn('category-export','选择某个分类导出','secondary',{},'download')}${btn('personal-export','选择学生导出','secondary',{},'download')}</div><p class="small muted">多级总表包括逐级小计及“日期 描述【分数】”。取最大值未选中的项目保留原分数并注明舍弃。查看历史公示请从“公示版本管理”下载对应版本。</p>${link('阅读各类表格说明','/manual#exports','btn ghost','book')}`,true);
A['category-export']=()=>modal('按分类导出表格',`<form data-form="category-export">${select('category_id','导出分类（包含全部下级）',[['','全部分类'],...nodesInOrder(latestRules().nodes).map(n=>[n.id,nodePath(n.id)])])}<p class="small muted">使用当前保存的规则。表内同时保留完整计算轨迹，便于核对上级封顶或取最大值的影响。</p>${actions('生成并下载分类表')}</form>`);
F['category-export']=async form=>{const url='/api/projects/'+pid()+'/export/xlsx'+(form.elements.category_id.value?'?category_id='+encodeURIComponent(form.elements.category_id.value):'');const response=await fetch(url,{credentials:'same-origin'});if(!response.ok){const data=await response.json();throw new Error(typeof data.detail==='string'?data.detail:'导出失败，请刷新后重试。');}saveBlob(await response.blob(),S.project.title+'-分类成绩汇总.xlsx');A.close();toast('分类表已生成，请查看浏览器的下载记录。');};

// Continuous review is implemented in review-ui.js.

async function publicListsView(){S.publics=await api('/api/public-lists');shell(heading('名单类奖项','在此维护名单类奖项。工程引用指定版本，修改名单后需要重新绑定才能应用。',link('导出名单目录','/api/export-tables/public-lists','btn secondary','download')+btn('public-new','新建名单类奖项','',{},'plus'))+`<div class="project-grid">${S.publics.map(l=>`<article class="card project-card"><div class="row between">${icon('file')}${tag(l.approved?'教师已确认':'草稿',l.approved?'':'amber')}</div><h2>${esc(l.name)}</h2><p class="small muted">${l.row_count} 行 · 版本 ${l.revision}</p><div class="project-card-bottom">${link('打开名单','#/public-lists/'+l.id,'btn secondary small-btn','arrow')}</div></article>`).join('')||empty('还没有名单类奖项','先上传一次统一证明，再填写对应学生与分值。',btn('public-new','新建名单类奖项','',{},'plus'))}</div>`,'public-lists','名单类奖项');}
A['public-new']=async()=>{S.publicContextProject=location.hash.startsWith('#/project/')&&S.project?.can_manage?S.project.id:null;S.publicEdit=null;location.hash='#/public-lists/new';};
async function publicEditor(id,revision){
 [S.students,S.template,S.publicRuleProjects]=await Promise.all([allStudents(),api('/api/rule-template'),api('/api/projects')]);
 S.publicEdit=id&&id!=='new'?await api('/api/public-lists/'+id+(revision?'?revision='+encodeURIComponent(revision):'')):{id:null,name:'',revision:0,owner_id:S.me.id,body:{resource_sha:'',source_name:'',description:'',note:'',rows:[],approved:false}};
 S.publicRows=structuredClone(S.publicEdit.body.rows);
 S.publicResource={sha256:S.publicEdit.body.resource_sha,name:S.publicEdit.body.source_name};
 S.publicRuleNodes=S.template.nodes;
 if(S.publicContextProject){const pr=await api('/api/projects/'+S.publicContextProject);S.publicRuleNodes=pr.body.rule_versions.at(-1).nodes;}
 publicEditorPaint();
}
function publicNodeOptions(){
 const nodes=S.publicRuleNodes||S.template.nodes;
 const options=nodes.filter(n=>!nodes.some(x=>x.parent===n.id)).map(n=>[n.id,nodePath(n.id,nodes)]);
 // Preserve historical/custom IDs when no reference project is selected; never silently reclassify.
 for(const row of S.publicRows)if(!options.some(o=>o[0]===row.category_id))options.push([row.category_id,'原有分类 '+row.category_id+'（请选择对应工程核对）']);
 return options;
}
function publicVersionTools(){
 const l=S.publicEdit;
 return `<div class="card pad" style="margin-bottom:18px"><div class="field-grid">${select('rule-reference','分类规则参考工程',[['','学院初始模板'],...(S.publicRuleProjects||[]).filter(p=>p.can_review).map(p=>[p.id,p.title])],S.publicContextProject||'','data-public-rule-project')}${l.id?select('list-version','查看名单版本',Array.from({length:l.latest_revision||l.revision},(_,i)=>[i+1,'第 '+(i+1)+' 版']),l.revision,'data-public-version'):''}</div><p class="small muted">分类参考仅用于选择分类，不会改写已有行。绑定时系统仍会核对目标工程的有效分类。历史版本只读；修改请打开最新版。</p></div>`;
}
function publicEditorPaint(){const l=S.publicEdit,editable=l.owner_id===S.me.id&&l.revision===(l.latest_revision||l.revision);const rowSample=S.publicRows[0]||{};shell(heading(l.id?l.name:'新建名单类奖项','支持名单型任职、公共活动、基础成绩认定。原始名单不向学生端开放。',(l.id?link('导出此保存版本','/api/public-lists/'+l.id+'/export?revision='+l.revision,'btn secondary','download'):'')+templateLink('public',S.publicContextProject)+link('返回名单库','#/public-lists','btn secondary','back'))+publicVersionTools()+`<form data-form="public-save" id="public-form"><div class="grid2"><section class="card pad"><h2>来源与说明</h2><div class="field-grid">${stampFields(l.body)}${field('name','名单名称',l.name,'text','required')}${field('source_name','佐证文件名称',S.publicResource.name,'text','readonly required')}<div class="span2">${area('description','名单内容说明',l.body.description)}</div><div class="span2">${area('note','教师内部备注 / 认定依据',l.body.note)}</div></div><div class="row wrap" style="margin-top:15px">${editable?btn('public-source','上传唯一佐证文件','secondary',{},'upload'):''}${S.publicResource.sha256?link('查看原始来源','/api/resources/'+S.publicResource.sha256,'btn ghost','eye'):''}</div></section><section class="card pad"><h2>新加名单行的默认值</h2><p class="small muted">只作用于之后加入的行；每行仍可单独修改。</p><div class="field-grid">${select('default_category','具体分类',publicNodeOptions(),rowSample.category_id||'positions')}${field('default_score','分值',rowSample.score||'0')}${field('default_description','具体加分项',rowSample.description||l.body.description||'')}${field('default_scenario','加分情形',rowSample.scenario||'')}${field('default_source','细则出处',rowSample.rule_source||'')}${field('default_date','材料有效日期（可按来源认定）',rowSample.material_date||'')}${select('default_status','认定状态',[['valid','有效'],['manual','需人工判断'],['out_of_scope','不属于加分情形'],['out_of_period','不在参评期']],rowSample.status||'valid')}</div></section></div><section class="card" style="margin-top:20px"><div class="card-head"><div><h2>名单明细 <span class="muted" id="public-row-count">${S.publicRows.length}</span></h2><p>姓名和学号来自学院名册，不手工重复录入身份。</p></div><div class="row wrap">${search('public-rows')}${editable?btn('public-add','选择学生','secondary',{},'users')+btn('public-import','导入表格','secondary',{},'upload'):''}</div></div><div class="table-wrap"><table><thead><tr><th>姓名 / 学号</th><th>班级</th><th>分类</th><th>情形</th><th>分值</th><th>状态</th><th>备注 / 操作</th></tr></thead><tbody id="public-rows">${publicRowsHTML(editable)}</tbody></table></div></section>${editable?`<section class="card pad" style="margin-top:20px"><label class="checkbox"><input type="checkbox" name="approved" ${l.body.approved?'checked':''}>我已核对来源、名单及每一行的评分依据，允许工程绑定此版本</label><div class="callout amber" style="margin-top:12px">标记“需人工判断”的行必须为0分，并将阻止相关学生被认定为完整最终成绩。A/B/C 等级缺少具体岗位或精确系数时，不应直接写成分数。</div><div class="form-actions"><button type="submit" class="btn">${l.id?'另存为新版本':'创建名单'}</button></div></section>`:''}</form>`,'public-lists',editable?'编辑名单':'查看名单版本');if(!editable)get('public-form').querySelectorAll('input,textarea,select').forEach(e=>e.disabled=true);}
function publicRowsHTML(editable=true){return S.publicRows.map((r,i)=>{const s=S.students.find(s=>s.id===r.student_id);return `<tr data-record-id="${r.id}" data-search="${esc((s?.name||'')+' '+(s?.number||'')+' '+(s?.class_name||'')+' '+r.description)}"><td><strong>${esc(s?.name||'学生')}</strong><div class="small mono muted">${esc(s?.number)}</div></td><td>${esc(s?.class_name||'—')}</td><td>${esc(publicNodeOptions().find(o=>o[0]===r.category_id)?.[1]||r.category_id)}</td><td>${esc(r.scenario)}<div class="small muted">${esc(r.description)}</div></td><td><input aria-label="${esc(s?.name)}分值" class="score-input" data-public-score="${i}" value="${esc(r.score)}" inputmode="decimal" ${editable?'':'readonly'}></td><td>${statusTag(r.status)}</td><td><div class="small muted">${esc(r.note||'—')}</div>${editable?btn('public-row-edit','详细编辑','ghost small-btn',{index:i},'edit')+btn('public-row-remove','移出','ghost small-btn',{index:i},'close'):''}</td></tr>`;}).join('');}
function refreshPublicRows(){markDirty();get('public-rows').innerHTML=publicRowsHTML();get('public-row-count').textContent=S.publicRows.length;enhanceCollections(get('main'));}
function publicDefaults(){const f=get('public-form');return {category_id:f.elements.default_category.value,score:f.elements.default_score.value,description:f.elements.default_description.value,scenario:f.elements.default_scenario.value,rule_source:f.elements.default_source.value,material_date:f.elements.default_date.value||null,status:f.elements.default_status.value,note:'',outcome_key:null,base_score:null,factors:[],denominator:'1'};}
A['public-source']=()=>modal('上传名单佐证',`<form data-form="public-source">${field('file','统一名单 / 认定来源文件','','file','accept=".pdf,.docx,.xlsx,.png,.jpg,.jpeg,.webp" required')}${actions('保存原始来源')}</form>`);
F['public-source']=async form=>{const fd=new FormData();fd.append('file',form.elements.file.files[0]);S.publicResource=await api('/api/uploads',{method:'POST',body:fd,raw:true});get('public-form').elements.source_name.value=S.publicResource.name;A.close();toast('原始来源已保存，保存名单后将固定引用。');};
A['public-add']=()=>modal('从学院名册选择学生',`<form data-form="public-add">${search('public-student-select')}<div class="check-list" id="public-student-select" style="margin-top:15px">${studentChecks(S.students,[])}</div><p class="small muted">可按班级搜索。重复加入同一学生是允许的，例如同一运动会的多个项目，但应区分成果键与加分情形。</p>${actions('加入所选学生')}</form>`,true);
F['public-add']=async form=>{const d=publicDefaults();for(const sid of new FormData(form).getAll('student_ids'))S.publicRows.push({...d,id:crypto.randomUUID(),student_id:sid});A.close();refreshPublicRows();};
A['public-row-remove']=b=>{S.publicRows.splice(Number(b.dataset.index),1);refreshPublicRows();};
A['public-row-edit']=b=>{const i=Number(b.dataset.index),r=S.publicRows[i],s=S.students.find(s=>s.id===r.student_id);modal('名单行 · '+s?.name,`<form data-form="public-row-edit" data-index="${i}"><div class="field-grid">${select('category_id','具体分类',publicNodeOptions(),r.category_id)}${select('status','认定状态',[['valid','有效'],['manual','需人工判断'],['out_of_scope','不属于加分情形'],['out_of_period','不在参评期']],r.status)}${field('score','本项分值',r.score,'text','required')}${field('material_date','材料有效日期',r.material_date||'')}${area('description','具体加分项',r.description,'required')}${area('scenario','具体情形',r.scenario)}${field('rule_source','细则出处',r.rule_source)}${field('outcome_key','成果键（跨个人材料去重）',r.outcome_key||'')}${field('base_score','基础分（可空）',r.base_score||'')}${field('factors','系数（逗号分隔）',(r.factors||[]).join(','))}${field('denominator','分母',r.denominator||'1')}${stampFields(r,true)}${area('note','内部备注',r.note)}</div>${actions('保存到名单草稿')}</form>`,true);};
F['public-row-edit']=async form=>{const d=formData(form);S.publicRows[Number(form.dataset.index)]={...S.publicRows[Number(form.dataset.index)],...d,...stampData(d),material_date:d.material_date||null,outcome_key:d.outcome_key||null,base_score:d.base_score||null,factors:d.factors?d.factors.split(/[,，]/).map(s=>s.trim()).filter(Boolean):[]};A.close();refreshPublicRows();};
A['public-import']=()=>modal('导入名单明细',`<form data-form="public-import"><p>使用下载模板。必要列：学号、分类ID、分数、描述、情形、规则出处、状态；其余列按模板填写。表格不会使用页面默认值补造缺失事实。</p><div class="callout amber">无法匹配学号、姓名冲突、重复成果等不会被静默忽略。导入是追加到编辑草稿，仍需最终保存和教师确认。</div>${templateLink('public',S.publicContextProject)}${field('file','选择表格','','file','accept=".csv,.xlsx" required')}${actions('解析并匹配学院名册')}</form>`);
F['public-save']=async form=>{const d=formData(form),l=S.publicEdit;if(!S.publicResource.sha256)throw new Error('请先上传统一来源文件。');const payload={revision:l.revision,name:d.name,body:{...stampData(d),resource_sha:S.publicResource.sha256,source_name:S.publicResource.name,description:d.description,note:d.note,rows:S.publicRows,approved:!!d.approved}},saved=await api('/api/public-lists'+(l.id?'/'+l.id:''),{method:l.id?'PUT':'POST',body:payload});S.publicEdit={...saved,owner_id:S.me.id};toast('名单已保存为版本 '+saved.revision+'。');if(S.publicContextProject&&saved.body.approved){modal('名单已确认',`<p>是否把版本 ${saved.revision} 绑定到刚才的综测工程？</p>${btn('bind-saved-public','绑定到工程','',{list:saved.id,revision:saved.revision,project:S.publicContextProject},'check')}${link('留在名单','#/public-lists/'+saved.id,'btn secondary')}`);}else location.hash='#/public-lists/'+saved.id;};
A['bind-saved-public']=async b=>{await loadProject(b.dataset.project);await updateProject('/api/projects/'+pid()+'/public-bindings','POST',{revision:S.project.revision,list_id:b.dataset.list,list_revision:Number(b.dataset.revision)});A.close();location.hash=purl('public');};
async function projectPublicView(){const p=S.project,b=p.body;if(!p.can_manage){paintProject('public',`<section class="card pad"><h2>统一信息录入由负责教师统一维护</h2><p class="muted">已绑定 ${new Set(b.public_bindings.map(x=>x.list_id)).size} 份名单类奖项。审核员可在计算结果中核对本班对应的名单行，但不能替换公共来源。</p>${link('查看计算明细',purl('calculation'),'btn secondary','arrow')}</section>`);return;}S.publics=await api('/api/public-lists');const boundNames=await api('/api/projects/'+pid()+'/bound-public-metadata');const bindings=[...new Map(b.public_bindings.map(v=>[v.list_id,v])).values()];paintProject('public',`<div class="section-heading"><div><h2>本工程的名单类奖项</h2><p>名单生成、公示和个人材料收集可以并行推进。</p></div><div class="row wrap">${projectTable('public','导出本工程名单类奖项')}${templateLink('public',pid())}${btn('bind-public','绑定已确认的名单','secondary',{},'plus')}${btn('public-new','新建名单类奖项','',{},'file')}</div></div><div class="project-grid">${bindings.map(v=>{const l=S.publics.find(x=>x.id===v.list_id);return `<section class="card project-card"><div class="row between">${icon('file')}${tag('固定版本 '+v.revision)}</div><h2>${esc(boundNames.find(x=>x.id===v.list_id)?.name||l?.name||v.list_id)}</h2><p class="small muted">绑定时间 ${fmt(v.bound_at)}</p>${l&&l.revision!==v.revision?'<div class="callout amber">名单库已有新版本 '+l.revision+'，当前工程仍使用旧版，需教师显式更新。</div>':''}<div class="row wrap">${link('查看绑定版本','#/public-lists/'+v.list_id+'/'+v.revision,'btn secondary small-btn','arrow')}${link('导出绑定版本','/api/public-lists/'+v.list_id+'/export?revision='+v.revision,'btn secondary small-btn','download')}${l&&l.approved&&l.revision!==v.revision?btn('bind-version','应用新版','small-btn',{list:v.list_id,revision:l.revision}):''}</div></section>`;}).join('')||empty('本工程尚未绑定名单类奖项','班委评议、公共活动名单和品德认定无需每位学生重复提交。')}</div><section class="card pad" style="margin-top:22px"><div class="row between wrap"><div><h2>学业成绩计算</h2><p class="muted">按课程学分计算加权成绩；等级制、未修读、缓考未出分与替代课程须保留处理依据。</p><p class="small">${b.academic_versions.length?'已保存 '+b.academic_versions.length+' 个成绩数据版本':'尚未录入课程成绩，缺少该项时无法发布完整最终成绩。'}</p></div>${btn('academic-editor','录入课程成绩','secondary',{},'chart')}</div></section><div class="callout" style="margin-top:18px">学校已核定的专业加权平均成绩也可通过名单类奖项录入 academic 分类，由该分类统一乘以0.86。不要同时录入平均成绩和课程明细。</div>`);}
A['bind-public']=async()=>{S.publics=await api('/api/public-lists');modal('选择要固定使用的名单版本',`<form data-form="bind-public">${select('list','已经由教师确认的名单',S.publics.filter(l=>l.approved).map(l=>[l.id,l.name+' · v'+l.revision]))}<div class="callout">系统只计入本工程参评学生的行；来源文件全局仍只存储一份。</div>${actions('绑定选中名单')}</form>`);};
F['bind-public']=async form=>{const l=S.publics.find(l=>l.id===form.elements.list.value);if(!l)throw new Error('没有可用的已确认名单。');await updateProject('/api/projects/'+pid()+'/public-bindings','POST',{revision:S.project.revision,list_id:l.id,list_revision:l.revision});A.close();await projectPublicView();};
A['bind-version']=async b=>{await updateProject('/api/projects/'+pid()+'/public-bindings','POST',{revision:S.project.revision,list_id:b.dataset.list,list_revision:Number(b.dataset.revision)});toast('已追加新版绑定记录；既有公示保持原样。');await projectPublicView();};

A['academic-editor']=()=>{S.academic=null;location.hash=purl('academic');};
function academicInit(){if(S.academic)return;const v=S.project.body.academic_versions.at(-1);S.academic=v?{resource_sha:v.resource_sha,courses:structuredClone(v.courses),students:structuredClone(v.students),confirmed:v.confirmed,note:v.note}:{resource_sha:'',courses:[],students:[],confirmed:false,note:''};S.academicStudent=S.academic.students[0]?.student_id||'';}
function collectAcademic(){const f=get('academic-form');if(!f)return;S.academic.note=f.elements.note.value;S.academic.confirmed=f.elements.confirmed.checked;S.academic.courses.forEach((c,i)=>{for(const key of ['name','credits','scheme'])c[key]=f.elements['course_'+i+'_'+key].value;});const row=S.academic.students.find(s=>s.student_id===S.academicStudent);if(row){row.entries=S.academic.courses.map((c,i)=>({course_id:c.id,score:f.elements['grade_'+i]?.value||null,excluded:!!f.elements['excluded_'+i]?.checked,exclusion_reason:f.elements['exclusion_reason_'+i]?.value||'',substitute_name:f.elements['substitute_'+i]?.value||null,substitution_reason:f.elements['substitution_reason_'+i]?.value||''}));}}
async function academicView(){academicInit();const a=S.academic,selected=a.students.find(s=>s.student_id===S.academicStudent);paintProject('public',`<div class="section-heading"><div><h2>课程成绩录入</h2><p>请录入参评课程及原始成绩；保存后由系统计算专业加权平均成绩。</p></div><div class="row wrap">${link('返回统一信息录入',purl('public'),'btn secondary','back')}${templateLink('academic',pid())}${projectTable('academic','导出已保存成绩')}${btn('academic-import','导入长表','secondary',{},'upload')}</div></div><form data-form="academic-save" id="academic-form"><section class="card pad"><div class="row between wrap"><div><h3>教务原始佐证</h3><p class="small mono muted resource-hash">${a.resource_sha?esc(a.resource_sha):'尚未上传官方成绩单 / 认定来源'}</p></div>${btn('academic-source','上传来源文件','secondary',{},'upload')}</div>${area('note','课程范围与特殊认定的依据',a.note,'required')}<label class="checkbox" style="margin-top:12px"><input type="checkbox" name="confirmed" ${a.confirmed?'checked':''}>教师已核对课程范围、学分和下列学生的完整成绩；所选学生未填写的参评课程将按0分计算</label></section><section class="card" style="margin-top:18px"><div class="card-head"><h2>参评课程 ${a.courses.length}</h2>${btn('course-add','添加课程','secondary small-btn',{},'plus')}</div><div class="table-wrap"><table><thead><tr><th>课程ID</th><th>课程名称</th><th>学分</th><th>成绩制</th><th></th></tr></thead><tbody>${a.courses.map((c,i)=>`<tr><td class="mono small">${esc(c.id)}</td><td><input aria-label="课程名称" name="course_${i}_name" value="${esc(c.name)}" required></td><td><input aria-label="课程学分" class="score-input" name="course_${i}_credits" value="${esc(c.credits)}" required></td><td>${select('course_'+i+'_scheme','',[['numeric','百分制'],['five','五级制'],['two','两级制，不计入']],c.scheme)}</td><td>${btn('course-remove','移除','ghost small-btn',{id:c.id},'close')}</td></tr>`).join('')}</tbody></table></div></section><section class="card pad" style="margin-top:18px"><div class="row between wrap"><div><h2>按学生录入</h2><p class="small muted">仅为已获得完整教务数据的学生建立成绩记录。</p></div>${btn('academic-students','选择已取得教务数据的学生','secondary',{},'users')}</div>${a.students.length?select('student-selector','选择学生',a.students.map(r=>{const s=studentById(r.student_id);return [r.student_id,s?.name+' · '+s?.number];}),S.academicStudent,'data-academic-student'):''}<div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>课程</th><th>成绩（空=未修读/未取得成绩）</th><th>免计入及依据</th><th>替代课程及依据</th></tr></thead><tbody>${selected?a.courses.map((c,i)=>{const g=selected.entries.find(g=>g.course_id===c.id)||{};return `<tr><td><strong>${esc(c.name)}</strong><p class="small">${esc(c.credits)} 学分</p></td><td>${c.scheme==='five'?select('grade_'+i,'',[['','未取得成绩'],['优秀','优秀'],['良好','良好'],['中等','中等'],['合格','合格'],['不合格','不合格']],g.score||''):field('grade_'+i,'',g.score||'','text','inputmode="decimal"')}</td><td><label class="checkbox"><input name="excluded_${i}" type="checkbox" ${g.excluded?'checked':''}>依规免计入</label>${field('exclusion_reason_'+i,'依据',g.exclusion_reason||'')}</td><td>${field('substitute_'+i,'替代课程',g.substitute_name||'')}${field('substitution_reason_'+i,'认定依据',g.substitution_reason||'')}</td></tr>`;}).join(''):'<tr><td colspan="4" class="muted">尚未选择有完整教务数据的学生。</td></tr>'}</tbody></table></div><div class="form-actions"><button type="submit" class="btn">校验并保存新的成绩版本</button></div></section></form>`);}
A['academic-source']=()=>{collectAcademic();modal('上传学业成绩认定来源',`<form data-form="academic-source">${field('file','原始成绩单或认定文件','','file','accept=".pdf,.xlsx,.docx,.png,.jpg" required')}${actions('上传并引用')}</form>`);};
F['academic-source']=async form=>{const fd=new FormData();fd.append('file',form.elements.file.files[0]);const r=await api('/api/uploads',{method:'POST',body:fd,raw:true});S.academic.resource_sha=r.sha256;A.close();await academicView();};
A['course-add']=()=>{collectAcademic();modal('添加参评课程',`<form data-form="course-add"><div class="field-grid">${field('id','课程唯一ID','','text','required')}${field('name','课程名称','','text','required')}${field('credits','学分','','text','required inputmode="decimal"')}${select('scheme','成绩制',[['numeric','百分制'],['five','五级制'],['two','两级制（不计入）']])}</div>${actions('添加到草稿')}</form>`);};
F['course-add']=async form=>{const c=formData(form);if(S.academic.courses.some(x=>x.id===c.id))throw new Error('课程ID重复。');S.academic.courses.push(c);A.close();await academicView();};
A['course-remove']=b=>{collectAcademic();S.academic.courses=S.academic.courses.filter(c=>c.id!==b.dataset.id);for(const s of S.academic.students)s.entries=s.entries.filter(e=>e.course_id!==b.dataset.id);academicView();};
A['academic-students']=()=>{collectAcademic();modal('具有完整教务数据的学生',`<form data-form="academic-students">${search('academic-select')}<div class="check-list" id="academic-select">${studentChecks(S.project.body.roster,S.academic.students.map(s=>s.student_id))}</div>${actions('确定录入范围')}</form>`,true);};
F['academic-students']=async form=>{const ids=new FormData(form).getAll('student_ids');S.academic.students=ids.map(id=>S.academic.students.find(s=>s.student_id===id)||{student_id:id,entries:[]});S.academicStudent=S.academic.students[0]?.student_id||'';A.close();await academicView();};
A['academic-import']=()=>{collectAcademic();modal('导入课程成绩长表',`<form data-form="academic-import"><p>每行一名学生的一门课程。必要表头：学号、课程ID、课程名称、学分、成绩制、成绩。成绩制使用 numeric / five / two。</p><p class="small muted">可选列：免计入（是/否）、免计入依据、替代课程、替代依据。导入将替换当前编辑草稿，不改写已保存的历史版本。</p>${templateLink('academic',pid())}${field('file','CSV / XLSX','','file','accept=".csv,.xlsx" required')}${actions('解析为课程与个人成绩')}</form>`);};
F['academic-save']=async()=>{collectAcademic();await updateProject('/api/projects/'+pid()+'/academic','PUT',{revision:S.project.revision,...S.academic});toast('成绩明细与计算依据已追加存档。');location.hash=purl('public');};

function scoreDisplay(value){const n=String(value??'0');if(!n.includes('.'))return n;const [a,b]=n.split('.');return b.length>6?a+'.'+b.slice(0,6)+'…':n;}
function traceHTML(r){return `<div class="table-wrap"><table><thead><tr><th>分类</th><th>原始输入和</th><th>聚合规则</th><th>聚合后</th><th>权重</th><th>封顶前</th><th>上限</th><th>封顶变化</th><th>最终值</th></tr></thead><tbody>${r.nodes.map(n=>`<tr><td><strong>${esc(n.name)}</strong><div class="small mono muted">${esc(n.id)}</div></td><td>${esc(scoreDisplay(n.raw_sum))}</td><td>${n.aggregate==='max'?'取最高':'求和'}${n.negative_policy==='separate'?' / 独立扣分':''}</td><td>${esc(scoreDisplay(n.selected_before_weight))}</td><td>${esc(n.weight)}</td><td>${esc(scoreDisplay(n.weighted_before_cap))}</td><td>${esc(n.cap??'—')}</td><td>${esc(n.cap_delta)}</td><td><strong>${esc(scoreDisplay(n.value))}</strong>${n.missing_required?tag('缺失','amber'):''}</td></tr>`).join('')}</tbody></table></div>`;}
async function calculationView(){S.calc=await api('/api/projects/'+pid()+'/calculation');const c=S.calc,p=S.project,nodes=latestRules().nodes,roots=S.resultColumns==='all'?nodesInOrder(nodes).filter(n=>n.parent):nodes.filter(n=>n.parent===nodes.find(n=>!n.parent).id);paintProject('calculation',`<div class="section-heading"><div><h2>计算结果与计算依据</h2><p>r${p.revision} · 规则版本 ${esc(c.rule_version_id.slice(0,8))} · 输入指纹 ${esc(c.input_hash.slice(0,14))}</p></div>${p.can_manage?link('导出多级总表','/api/projects/'+pid()+'/export/xlsx','btn secondary','download')+btn('category-export','按分类导出','secondary',{},'download'):''}</div><div class="grid3"><div class="card stat"><span>待处理问题</span><div class="number">${c.issue_count}</div></div><div class="card stat"><span>基础认定不全</span><div class="number">${c.missing_baseline_count}</div></div><div class="card stat"><span>最终公示条件</span><div class="number" style="font-size:25px">${c.ready?'已满足':'未满足'}</div></div></div>${!c.ready?'<div class="callout amber" style="margin:18px 0">下表是当前已认定输入的计算结果，不是完整最终综测。未提供的学业成绩、思想品德认定以及待审核材料不会被默认为已完成。</div>':''}<section class="card" style="margin-top:18px"><div class="card-head"><h3>学生计算明细</h3><div class="row wrap">${search('calculation-table')}${btn('all-achievements','所有成果','secondary small-btn')}${btn('result-columns',S.resultColumns==='all'?'仅显示一级分类':'显示全部分类','secondary small-btn')}</div></div><div class="table-wrap"><table><thead><tr><th>学生 / 学号</th>${roots.map(n=>`<th>${esc(n.name)}${n.cap!==null?' ≤'+esc(n.cap):''}</th>`).join('')}<th>当前计算值</th><th>完整性</th><th>操作</th></tr></thead><tbody id="calculation-table">${Object.entries(c.students).map(([sid,r])=>{const s=studentById(sid);return `<tr data-record-id="${sid}" data-search="${esc(s?.name+' '+s?.number)}"><td><strong>${esc(s?.name)}</strong><div class="small mono muted">${esc(s?.number)}</div></td>${roots.map(n=>`<td>${btn('open-achievements',scoreDisplay(r.nodes.find(t=>t.id===n.id)?.value),'text-link',{sid,category:n.id})}</td>`).join('')}<td class="score"><strong>${esc(r.display_total)}</strong></td><td>${tag(r.ready?'输入完整':r.issues.length?'有待办':'缺基础认定',r.ready?'':'amber')}</td><td>${btn('student-trace','查看明细','secondary small-btn',{sid},'arrow')}</td></tr>`;}).join('')}</tbody></table></div></section>`);}
function resultDetailHTML(r){return `${r.issues?.length?'<div class="callout amber"><strong>需要处理</strong><p>'+r.issues.map(i=>esc(i.message)).join('<br>')+'</p></div>':''}<h3 style="margin-top:18px">分类计算过程</h3>${traceHTML(r)}<h3 style="margin-top:24px">个人材料认定</h3><div class="table-wrap"><table><thead><tr><th>图片</th><th>材料与认定</th><th>局部分</th><th>计入说明</th></tr></thead><tbody>${(r.materials||[]).map(m=>`<tr><td><a href="${evidenceImage(m.id,true)}" target="_blank" rel="noopener"><img class="evidence-thumb" loading="lazy" src="${evidenceImage(m.id)}" alt="材料原件"></a></td><td>${statusTag(m.annotation.status)}<p>${esc(m.annotation.description)}</p><p class="small muted">${esc(m.annotation.rule_item)} · ${esc(m.annotation.scenario)}</p><p class="small muted">${esc(m.annotation.rule_source)}</p>${m.annotation.student_note?'<p class="pre-wrap"><strong>审核说明：</strong>'+esc(m.annotation.student_note)+'</p>':''}<p class="small muted">是否有盖章：${m.annotation.has_stamp===true?'是':m.annotation.has_stamp===false?'否':'未判定'}；盖章文字：${esc(m.annotation.stamp_text||'未填写')}</p></td><td>${esc(m.annotation.score)}</td><td>${esc(m.excluded_reason||'有效输入；是否最终计入由上方聚合轨迹决定')}${S.project.can_review&&S.project.body.evidence?.find(e=>e.id===m.id)?.student_id!==S.me.student_id?btn('jump-evidence','打开标注','ghost small-btn',{id:m.id}):''}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">没有个人材料。</td></tr>'}</tbody></table></div><h3 style="margin-top:24px">名单类奖项对应行</h3><div class="table-wrap"><table><thead><tr><th>来源 / 固定版本</th><th>具体情形</th><th>状态</th><th>局部分</th></tr></thead><tbody>${(r.public_rows||[]).map(row=>`<tr><td>${S.me.role==='teacher'?link(row.list_name+' · v'+row.list_revision,'#/public-lists/'+row.list_id+'/'+row.list_revision,'text-link'):esc(row.list_name)+' · v'+row.list_revision}</td><td>${esc(row.description)}<p class="small muted">${esc(row.scenario)} · ${esc(row.rule_source)}</p></td><td>${statusTag(row.status)}</td><td>${esc(row.score)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">没有名单类奖项行。</td></tr>'}</tbody></table></div>${r.academic?`<details style="margin-top:18px"><summary>专业加权平均成绩的课程计算明细</summary><pre>${esc(JSON.stringify(r.academic,null,2))}</pre></details>`:''}`;}
A['student-trace']=b=>{const r=S.calc.students[b.dataset.sid],s=studentById(b.dataset.sid);modal((s?.name||'学生')+' · 计算明细',`<div class="score-hero"><span>${r.ready?'当前计算总分':'已认定输入的当前计算值（非最终）'}</span><strong>${esc(r.display_total)}</strong></div>${resultDetailHTML(r)}${S.project.can_manage?'<div class="form-actions">'+link('导出个人PDF','/api/projects/'+pid()+'/export/student/'+b.dataset.sid,'btn secondary','download')+link('导出个人成果表','/api/projects/'+pid()+'/export/student/'+b.dataset.sid+'/xlsx','btn secondary','download')+'</div>':''}`,true);};

async function publicationView(){const p=S.project,b=p.body;if(!p.can_manage&&!p.can_review)return personalPublication();let own='';if(S.me.student_id&&b.student_ids.includes(S.me.student_id))own=btn('my-result','查看我自己的公示结果','secondary',{},'eye');const snapshots=b.snapshots||[],appeals=b.appeals||[];paintProject('publication',`<div class="section-heading"><div><h2>公示版本管理</h2><p>每位学生只看到自己的材料评分与计算过程。补充材料不改变已经公示的历史版本。</p></div><div class="row wrap">${own}${p.can_manage?btn('publish','创建公示快照','',{},'eye'):''}</div></div><div class="callout">申诉截止：${fmt(b.schedule?.appeal_deadline)}。可以多轮核算、多轮公示；班级与学院正式公示程序仍须按学院细则组织。</div><section class="card" style="margin-top:18px"><div class="card-head"><h2>公示版本 ${snapshots.length}</h2>${projectTable('publications','导出公示目录')}</div><div class="table-wrap"><table><thead><tr><th>版本 / 名称</th><th>类型</th><th>发布时间</th><th>输入指纹</th><th>缺失 / 问题</th><th>导出</th></tr></thead><tbody>${snapshots.map(s=>`<tr><td><strong>v${s.version} · ${esc(s.label)}</strong>${s.id===b.publication_id?tag('学生当前可见'):''}</td><td>${tag(s.mode==='final'?'最终':'阶段性',s.mode==='final'?'':'amber')}</td><td>${fmt(s.created_at)}</td><td class="mono small">${esc(s.input_hash.slice(0,18))}</td><td>${s.missing_baseline_count} / ${s.issue_count}</td><td>${S.me.role==='teacher'?link('此公示版本总表','/api/projects/'+pid()+'/export/xlsx?snapshot_id='+s.id,'btn secondary small-btn','download'):''}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">尚未公示。学生无法通过接口提前查看分数。</td></tr>'}</tbody></table></div></section><section class="card" style="margin-top:18px"><div class="card-head"><div><h2>补交与异议申请 ${appeals.length}</h2><p>不接受私聊覆盖原件。批准有明确的补交有效期，处理过程留痕。</p></div>${projectTable('appeals','导出申请记录')}${search('appeal-table')}</div><div class="table-wrap"><table><thead><tr><th>申请人</th><th>原因 / 提交时间</th><th>状态 / 处理说明</th><th>操作</th></tr></thead><tbody id="appeal-table">${appeals.map(a=>{const s=studentById(a.student_id),h=a.history.at(-1);return `<tr data-record-id="${a.id}" data-search="${esc(s?.name+' '+s?.number+' '+(!h?'待处理':''))}"><td>${esc(s?.name)}</td><td>${esc(reasons[a.reason])}<p class="small muted">${fmt(a.created_at)}</p></td><td>${tag(!h?'待处理':h.decision==='approved'?'批准补交':'不予批准',!h?'amber':'gray')}<p class="small muted">${esc(h?.note||'')}${h?.until?' · 至 '+fmt(h.until):''}</p></td><td>${p.can_manage?btn('appeal-decision','处理申请','secondary small-btn',{id:a.id}):''}</td></tr>`;}).join('')||'<tr><td colspan="4" class="muted">尚无申请。</td></tr>'}</tbody></table></div></section>`);}
async function personalPublication(){const p=S.project;let data;try{data=await api('/api/projects/'+pid()+'/my-result');}catch(e){if(e.status!==403)throw e;paintProject('publication',empty('尚未公示','老师公示后，你才能在这里看到每项材料的认定和完整计算过程。',link('返回提交材料',purl('submission'),'btn secondary','back')));return;}const r=data.result;paintProject('publication',`<div class="score-hero"><span>${esc(data.label)} · v${data.version}</span><strong>${esc(r.display_total)}</strong><p>${data.mode==='final'?'最终公示结果':'阶段性计算结果 · 不代表完整最终成绩'}</p><div class="row center wrap">${tag('仅本人可见')}${tag(fmt(data.published_at),'gray')}${link('导出我的材料PDF','/api/projects/'+pid()+'/export/student/'+S.me.student_id,'btn secondary small-btn','download')}${link('导出我的成果表','/api/projects/'+pid()+'/export/student/'+S.me.student_id+'/xlsx','btn secondary small-btn','download')}${btn('appeal','提出异议 / 申请补交','secondary small-btn')}</div></div><section class="card pad" style="margin-top:18px">${resultDetailHTML(r)}</section><section class="card pad" style="margin-top:18px"><h2>我的申请</h2>${(p.body.appeals||[]).map(a=>`<div class="document"><div><strong>${esc(reasons[a.reason])}</strong><p class="small muted">${fmt(a.created_at)} · ${a.history.at(-1)?a.history.at(-1).decision==='approved'?'已批准':'未批准':'待处理'}</p><p class="small">${esc(a.history.at(-1)?.note||'')}</p></div>${a.history.at(-1)?.decision==='approved'?btn('supplement','去补交','secondary small-btn',{evidence:a.evidence_id||'',request:a.id}):''}</div>`).join('')||'<p class="muted">没有申请记录。</p>'}</section>`);}
A['my-result']=async()=>{await personalPublication();};
A.publish=()=>modal('创建新的公示快照',`<form data-form="publish">${field('label','公示名称','','text','required placeholder="班级第一轮公示"')}${select('mode','公示类型',[['provisional','阶段性公示（明确保留未完成状态）'],['final','最终公示（全部完成且申诉窗口关闭）']])}<div class="callout amber">最终公示会被服务端严格校验。资料未齐时只能进行阶段性公示。已有公示结果不会被覆盖。</div>${actions('创建公示快照')}</form>`);
F.publish=async form=>{await updateProject('/api/projects/'+pid()+'/publish','POST',{revision:S.project.revision,...formData(form)});A.close();toast('新公示已生效，学生仅能查看自己的结果。');await publicationView();};
A.appeal=()=>modal('提交补交或异议申请',`<form data-form="appeal">${select('reason','请选择申请原因',Object.entries(reasons))}${select('evidence_id','涉及的材料（可不选）',[['','补交新成果 / 整体结果'],...ownEvidence().map(e=>[e.id,fmt(e.submitted_at)+' · '+e.id.slice(0,8)])])}<div class="callout">申请不要求填写文字。补充证明仍然只提交图片。老师的处理与允许补交的截止时间会保留在记录中。</div>${actions('提交申请')}</form>`);
F.appeal=async form=>{const d=formData(form);await api('/api/projects/'+pid()+'/appeals',{method:'POST',body:{reason:d.reason,evidence_id:d.evidence_id||null}});A.close();await loadProject(pid());toast('申请已保存。');await personalPublication();};
A['appeal-decision']=b=>modal('处理补交或异议申请',`<form data-form="appeal-decision" data-id="${b.dataset.id}">${select('decision','处理结论',[['approved','批准补交'],['rejected','不予批准']])}${field('until','允许补交至（批准时必填）',localDate(new Date(Date.now()+86400000).toISOString()),'datetime-local')}${area('note','统一、可追溯的处理依据','','required')}${actions('保存处理记录')}</form>`);
F['appeal-decision']=async form=>{const d=formData(form);await updateProject('/api/projects/'+pid()+'/appeals/'+form.dataset.id+'/decision','POST',{revision:S.project.revision,decision:d.decision,note:d.note,until:d.decision==='approved'&&d.until?new Date(d.until).toISOString():null});A.close();toast('已保存申请处理记录。');await publicationView();};
A.supplement=b=>{S.supplementFor=b.dataset.evidence||null;S.requestId=b.dataset.request||null;location.hash=purl('submission');};

async function archiveView(){const p=S.project,b=p.body;paintProject('archive',`<div class="section-heading"><div><h2>工程导出与归档</h2><p>一个 .zcp 文件对应一个班级工程，包括原件、版本、规则、名单与公示快照。</p></div></div><div class="grid3"><section class="card archive-card">${icon('archive')}<h2>完整工程文件</h2><p>独立存档与迁移，逐文件校验 SHA-256；不包含密码、会话或服务令牌。</p>${p.can_manage?link('导出 .zcp','/api/projects/'+pid()+'/export/project','btn','download'):'<p class="muted">仅负责教师可导出。</p>'}</section><section class="card archive-card">${icon('chart')}<h2>只读计算汇总</h2><p>XLSX 含全部分类的多级表头、逐级小计和成果描述，并保留取最大值时舍弃的项目。导出文件不能修改系统中的原始记录。</p>${S.me.role==='teacher'?link('导出 XLSX','/api/projects/'+pid()+'/export/xlsx','btn secondary','download'):''}</section><section class="card archive-card">${icon('file')}<h2>个人材料包</h2><p>每页一张个人证明图片，上方列出结构化标注；长说明按同一材料续页。名单类奖项和课程信息请使用个人成果表。</p>${p.can_manage?btn('personal-export','选择学生导出','secondary',{},'download'):''}</section></div><section class="card pad" style="margin-top:20px"><h2>结项与归档</h2><p class="muted">结项须有最终公示，且当前输入指纹与最终快照一致。归档后不再允许新增材料、标注或规则。</p><div class="row wrap">${p.can_manage&&b.state!=='archived'?btn('transition',b.state==='closed'?'归档工程':'完成结项','secondary',{state:b.state==='closed'?'archived':'closed'},'shield'):tag(b.state==='archived'?'工程已归档':'仅负责教师可结项与归档','gray')}${S.me.role==='teacher'?link('下载只读材料包','/api/projects/'+pid()+'/export/materials','btn secondary','download'):''}${p.can_manage?btn('project-audit','查看工程审计日志','secondary',{},'clock'):''}</div></section>${b.meta.import_unverified?`<section class="card pad" style="margin-top:20px"><h2>此工程是外部导入件</h2><div class="callout amber">哈希校验只能检测损坏，不能证明提交者身份或材料真实性。新实例不会继承旧审核权限，也不会自动开放旧公示。</div>${p.can_manage?btn('ack-import','核对并确认来源','secondary',{},'check'):''}</section>`:''}<div class="callout amber" style="margin-top:20px">完整工程包含学生个人信息，必须保存在受控位置。传输和离线备份请另行加密，不能发送到班级公共群。</div>`);}
A['personal-export']=()=>modal('导出个人规范材料包',`<div class="check-list">${S.project.body.roster.map(s=>`<div class="check-item"><div class="grow"><strong>${esc(s.name)}</strong><div class="small mono muted">${esc(s.number)}</div></div>${link('成果表','/api/projects/'+pid()+'/export/student/'+s.id+'/xlsx','btn secondary small-btn','download')}${link('图片PDF','/api/projects/'+pid()+'/export/student/'+s.id,'btn secondary small-btn','download')}</div>`).join('')}</div>`);
A['project-audit']=async()=>{const data=await api('/api/projects/'+pid()+'/audit');modal('工程审计日志',projectTable('audit','导出工程审计表')+auditHTML(data),true);};
A['ack-import']=()=>modal('核对导入工程来源',`<form data-form="ack-import">${area('note','说明原始来源、核验方式与负责人','','required')}<div class="callout amber">来源确认不等于人工核对全部标注。请继续处理待办材料，再按规定公示。请另行处理所有待办。</div>${actions('确认来源')}</form>`);
F['ack-import']=async form=>{await updateProject('/api/projects/'+pid()+'/acknowledge-import','POST',{revision:S.project.revision,note:form.elements.note.value});A.close();toast('来源确认已留痕。');await archiveView();};

async function agentsView(){const [tokens,projects]=await Promise.all([api('/api/agent-tokens'),api('/api/projects')]);S.tokens=tokens;S.projects=projects;shell(heading('外部 Agent 接口','系统本身不调用模型。外部服务取得限定工程、限定能力、短时有效的令牌后进行局部标注。',btn('token-create','创建短期服务令牌','',{},'plus'))+`<div class="grid2"><section class="card pad"><h2>外部 Agent 接入步骤</h2><div class="timeline"><div class="timeline-item"><strong>01 · 安装随代码包提供的 skill</strong><p class="small muted">使用 agent/install.py 安装到外部 Agent 的技能目录；设置 ZC_BASE_URL、ZC_PROJECT_ID 与 ZC_TOKEN。</p></div><div class="timeline-item"><strong>02 · 自动获取工程上下文</strong><p class="small muted">manifest → 原始细则、多文件源、学院解释、规则分类树、学生与未标注队列。</p></div><div class="timeline-item"><strong>03 · 幂等提交逐项标注</strong><p class="small muted">带工程修订号和标注版本号写入。冲突重新读取；不覆盖人工核对，不应用全局封顶。</p></div></div>${link('外部AI接入与表格回填指南','/ai-guide','btn secondary','book')}${link('接口规范','/api/openapi.json','btn ghost','code')}</section><section class="card pad"><h2>接口权限说明</h2><p class="muted">Agent 只能处理获授权工程的上下文、图片、标注和名单类奖项草稿。</p><div class="callout">不能设置规则、管理账号、修改时间、确认“人工已核对”、发布结果、做最终评分裁决或进入管理员后台。</div><p class="small muted">证书或名单中的文字永远是待检查的数据，不能成为工具调用指令。缺失事实必须标为待人工判断。</p></section></div><section class="card" style="margin-top:20px"><div class="card-head"><h2>我的服务令牌</h2></div><div class="table-wrap"><table><thead><tr><th>名称 / 工程</th><th>能力</th><th>到期</th><th>状态</th><th>操作</th></tr></thead><tbody>${tokens.map(t=>`<tr><td><strong>${esc(t.name)}</strong><p class="small muted">${esc(projects.find(p=>p.id===t.project_id)?.title||t.project_id)}</p></td><td class="small mono">${t.scopes.map(esc).join('<br>')}</td><td>${fmt(t.expires_at)}</td><td>${tag(t.revoked?'已撤销':Date.parse(t.expires_at)<Date.now()?'已到期':'生效',t.revoked?'gray':'')}</td><td>${!t.revoked?btn('token-revoke','立即撤销','ghost small-btn',{id:t.id},'close'):''}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">尚未签发令牌。</td></tr>'}</tbody></table></div></section>`,'agents','Agent 接口');}
A['token-create']=()=>modal('签发限定工程的短期令牌',`<form data-form="token-create">${select('project_id','授权的工程',S.projects.filter(p=>p.can_manage).map(p=>[p.id,p.title]))}${field('name','服务身份名称','','text','required placeholder="材料录入 Agent"')}${field('hours','有效小时数（最多168）','24','number','min="1" max="168" required')}<label class="checkbox"><input type="checkbox" name="public_write">同时允许创建名单类奖项草稿（不能确认或发布）</label>${actions('生成一次性可见令牌')}</form>`);
F['token-create']=async form=>{const d=formData(form),scopes=['context:read','evidence:read','annotation:write'];if(d.public_write)scopes.push('public:write');const r=await api('/api/agent-tokens',{method:'POST',body:{project_id:d.project_id,name:d.name,hours:Number(d.hours),scopes}});S.tokenSecret=r.token;modal('请私密保存令牌',`<div class="callout amber">完整令牌只显示这一次。不要放入提示词日志、Git 仓库或群聊。到期后重新签发。</div>${area('token','服务令牌',r.token,'readonly class="mono"')}<p class="small muted">到期：${fmt(r.expires_at)}</p>${btn('token-copy','复制令牌','secondary',{},'copy')}`);await agentsView();};
A['token-copy']=async()=>{await navigator.clipboard.writeText(S.tokenSecret);toast('已复制到剪贴板，请保管好。');};
A['token-revoke']=async b=>{await api('/api/agent-tokens/'+b.dataset.id,{method:'DELETE'});toast('令牌已撤销。');await agentsView();};
function auditHTML(events){return `<div class="table-wrap"><table><thead><tr><th>时间</th><th>事件</th><th>执行身份</th><th>详情</th></tr></thead><tbody>${events.map(e=>`<tr><td class="no-wrap">${fmt(e.created_at)}</td><td class="mono small">${esc(e.action)}</td><td class="small">${esc(e.actor_kind)}<div class="mono muted">${esc(e.actor_id?.slice(0,14))}</div></td><td><details><summary>查看事件与签名</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div>`;}
async function opsView(){const s=await api('/api/ops/stats');shell(heading('运维控制台','唯一管理员账户。这里管理运行状态、账号、日志与反馈，不参与学生材料认定。')+`<div class="grid4">${[['学院',s.colleges],['账户',s.accounts],['工程',s.projects],['已存资源',s.resources]].map(([t,n])=>`<section class="card stat"><span>${t}</span><div class="number">${n}</div></section>`).join('')}</div><div class="grid2" style="margin-top:20px"><section class="card pad"><h2>运行环境</h2><div class="snapshot"><span class="grow muted">应用版本</span><strong>${esc(s.version)}</strong></div><div class="snapshot"><span class="grow muted">环境</span>${tag(s.environment,s.environment==='production'?'':'amber')}</div><div class="snapshot"><span class="grow muted">数据库</span><strong>${esc(s.database)}</strong></div><div class="snapshot"><span class="grow muted">原始文件大小</span><strong>${size(s.stored_bytes)}</strong></div><div class="snapshot"><span class="grow muted">上传病毒扫描配置</span>${tag(s.scanner_configured?'已配置':'未配置',s.scanner_configured?'':'amber')}</div><div class="snapshot"><span class="grow muted">管理员动态口令</span>${tag(s.admin_mfa_configured?'已配置':'未配置',s.admin_mfa_configured?'':'amber')}</div><p class="small muted">“已配置”不代表实时健康检查已通过。生产部署必须实际验证扫描服务、备份恢复和HTTPS终止。</p></section><section class="card pad"><h2>管理功能</h2><div class="workflow"><a class="workflow-card" href="#/ops-accounts">${icon('users')}<div><h3>学院与账号管理</h3><p>创建教师、停用账号、重置密码</p></div></a><a class="workflow-card" href="#/ops-feedback">${icon('message')}<div><h3>用户反馈 ${s.feedback}</h3><p>图片、文字与录屏，只有管理员可见</p></div></a><a class="workflow-card" href="#/ops-audit">${icon('shield')}<div><h3>签名事件日志</h3><p>操作身份、时间、对象与事件详情</p></div></a></div></section></div>`,'ops','运维概览');}
async function opsAccountsView(){S.opsOffset=S.opsOffset||0;[S.colleges,S.accounts]=await Promise.all([api('/api/ops/colleges'),api('/api/ops/accounts?offset='+S.opsOffset)]);shell(heading('学院与账号','管理员只有一个；教师只能由管理员创建；学生由各学院教师名单导入。',link('导出账号目录','/api/ops/export-table/accounts','btn secondary','download')+btn('college-create','添加学院','secondary',{},'plus')+btn('teacher-create','创建教师','',{},'users'))+`<section class="card pad"><h2>学院 ${S.colleges.length}</h2><div class="row wrap">${S.colleges.map(c=>tag(c.name,'gray')).join('')||'<span class="muted">尚未创建学院。</span>'}</div></section><section class="card" style="margin-top:18px"><div class="card-head"><h2>账号列表</h2>${search('ops-accounts-table')}</div><div class="table-wrap"><table><thead><tr><th>姓名</th><th>登录名</th><th>角色 / 学院</th><th>状态</th><th>操作</th></tr></thead><tbody id="ops-accounts-table">${S.accounts.map(a=>`<tr data-search="${esc(a.name+' '+a.username)}"><td>${esc(a.name)}</td><td class="mono">${esc(a.username)}</td><td>${{admin:'唯一管理员',teacher:'教师',student:'学生'}[a.role]}<p class="small muted">${esc(S.colleges.find(c=>c.id===a.college_id)?.name||'系统')}</p></td><td>${tag(a.disabled?'停用':a.must_change?'待改初始密码':'正常',a.disabled?'red':a.must_change?'amber':'')}</td><td>${a.role!=='admin'?btn('account-toggle',a.disabled?'启用':'停用','ghost small-btn',{id:a.id,disabled:!a.disabled})+btn('reset-password','重置密码','ghost small-btn',{id:a.id,name:a.name}):tag('不可删除 / 停用','gray')}</td></tr>`).join('')}</tbody></table></div><div class="card-head"><p class="small muted">第 ${S.opsOffset+1} 至 ${S.opsOffset+S.accounts.length} 条</p><div class="row">${S.opsOffset?btn('ops-page','上一页','secondary small-btn',{delta:-100}):''}${S.accounts.length===100?btn('ops-page','下一页','secondary small-btn',{delta:100}):''}</div></div></section>`,'ops-accounts','账号管理');}
A['ops-page']=async b=>{S.opsOffset=Math.max(0,(S.opsOffset||0)+Number(b.dataset.delta));await opsAccountsView();};
A['college-create']=()=>modal('创建学院',`<form data-form="college-create">${field('name','学院名称','','text','required')}${actions('创建学院')}</form>`);
F['college-create']=async form=>{await api('/api/ops/colleges',{method:'POST',body:formData(form)});A.close();toast('学院已创建。');await opsAccountsView();};
A['teacher-create']=()=>modal('创建教师账号',`<form data-form="teacher-create">${select('college_id','所属学院',S.colleges.map(c=>[c.id,c.name]))}${field('name','教师姓名','','text','required')}${field('username','登录名','','text','required minlength="3"')}<p class="small muted">初始密码随机生成，只显示一次。教师首次登录必须修改。</p>${actions('创建教师')}</form>`);
F['teacher-create']=async form=>{const r=await api('/api/ops/teachers',{method:'POST',body:formData(form)});await opsAccountsView();credentialsModal([r],'教师账户已创建');};
A['account-toggle']=async b=>{await api('/api/ops/accounts/'+b.dataset.id,{method:'PATCH',body:{disabled:b.dataset.disabled==='true'}});toast('账号状态已更新。');await opsAccountsView();};
async function opsFeedbackView(){S.feedbacks=await api('/api/ops/feedback?offset='+(S.feedbackOffset||0));shell(heading('用户反馈','仅此管理员可查看全部反馈及附件。反馈不进入评分流程。',link('导出反馈表','/api/ops/export-table/feedback','btn secondary','download')+link('导出全部记录JSON','/api/ops/feedback-export','btn secondary','download'))+`<div class="stack">${S.feedbacks.map(f=>`<section class="card pad"><div class="row between wrap"><div><strong>${fmt(f.created_at)}</strong><p class="small mono muted">用户 ${esc(f.account_id)}</p></div>${select('status','处理状态',[['new','新反馈'],['triaged','已登记'],['planned','已纳入计划'],['resolved','已解决']],f.status,'data-feedback-status="'+f.id+'"')}</div><p class="pre-wrap">${esc(f.text)}</p><div class="row wrap">${f.attachments.map(a=>link(a.name+' · '+size(a.size),'/api/resources/'+a.sha256,'btn secondary small-btn',a.media_type.startsWith('image/')?'image':'file')).join('')}</div></section>`).join('')||empty('还没有反馈','用户可以在学生端或教师端发送文字、图片与录屏。')}</div><div class="form-actions">${S.feedbackOffset?btn('feedback-page','上一页','secondary',{delta:-100}):''}${S.feedbacks.length===100?btn('feedback-page','下一页','secondary',{delta:100}):''}</div>`,'ops-feedback','反馈管理');}
A['feedback-page']=async b=>{S.feedbackOffset=Math.max(0,(S.feedbackOffset||0)+Number(b.dataset.delta));await opsFeedbackView();};
async function opsAuditView(){const events=await api('/api/ops/audit?offset='+(S.auditOffset||0));shell(heading('系统审计日志','查看各项操作的时间、执行者和对象。已记录的事件不能通过系统修改或删除。',link('导出审计表','/api/ops/export-table/audit','btn secondary','download')+link('导出原始日志JSONL','/api/ops/audit-export','btn secondary','download'))+`<section class="card">${auditHTML(events)}</section><div class="form-actions">${S.auditOffset?btn('audit-page','上一页','secondary',{delta:-100}):''}${events.length===100?btn('audit-page','下一页','secondary',{delta:100}):''}</div><div class="callout amber">数据库超级用户与掌握密钥的运维仍是信任边界。正式部署应把审计事件定期导出至独立的不可改写备份中。</div>`,'ops-audit','审计日志');}
A['audit-page']=async b=>{S.auditOffset=Math.max(0,(S.auditOffset||0)+Number(b.dataset.delta));await opsAuditView();};

/* Navigation and all event delegation live here; no inline executable handlers. */
async function route(){
 if(!S.me){renderLogin();return;}if(S.me.must_change){showPassword();return;}
 const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean),page=parts[0]||(S.me.role==='admin'?'ops':'workspace');
 try{
  if(page==='project'){
   if(!parts[1])throw new Error('工程地址不完整。');const changed=S.project?.id!==parts[1];if(changed){S.dirtyRules=false;S.ruleDraft=null;S.academic=null;S.reviewId=null;S.requestId=null;S.supplementFor=null;S.reviewSession=null;S.reviewAttempt=null;}
   await loadProject(parts[1]);let tab=parts[2]||'overview';if(!S.project.can_review&&!['submission','publication'].includes(tab))tab='submission';
   const views={overview:projectOverview,setup:setupView,submission:submissionView,review:reviewView,public:projectPublicView,academic:academicView,calculation:calculationView,publication:publicationView,archive:archiveView};
   if(!views[tab])throw new Error('此工程页面不存在。');if(tab==='academic'&&!S.project.can_manage)throw new Error('课程录入仅向负责教师开放。');await views[tab]();
  }else if(page==='public-lists'&&parts[1])await publicEditor(parts[1],parts[2]);
  else {const views={workspace,students:studentsView,'public-lists':publicListsView,agents:agentsView,ops:opsView,'ops-accounts':opsAccountsView,'ops-feedback':opsFeedbackView,'ops-audit':opsAuditView};if(!views[page])throw new Error('页面不存在。');await views[page]();}
  window.scrollTo({top:0,behavior:'instant'});
 }catch(e){if(S.me)shell(empty('页面无法打开',e.message,link('返回工作空间',S.me.role==='admin'?'#/ops':'#/workspace','btn secondary','back')));toast(e.message,true);}
}
async function runAction(el){const f=A[el.dataset.action];if(!f){toast('操作未能执行，请刷新页面后重试，并向管理员提供当前页面和操作步骤。',true);return;}if(el.disabled)return;el.disabled=true;try{await f(el);}catch(e){showUIError(e);if(e.status===409)toast('未覆盖任何数据。请刷新页面，重新核对最新版本后提交。',true);}finally{if(el.isConnected)el.disabled=false;}}
document.addEventListener('click',e=>{const nav=e.target.closest('a[href^="#/"]');if(nav&&nav.hash!==location.hash&&hasUnsavedWork()){if(!window.confirm('当前页面有未保存的内容。离开后未保存的修改可能丢失。是否继续？')){e.preventDefault();return;}clearDirty();S.dirtyRules=false;}const el=e.target.closest('[data-action]');if(el){e.preventDefault();runAction(el);}else if(e.target.closest('dialog a[href^="#/"]'))A.close();});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const fn=F[f.dataset.form];if(!fn)return;const b=f.querySelector('button[type="submit"]');if(b?.disabled)return;if(b)b.disabled=true;try{await fn(f);if(['public-save','academic-save','annotation','instructions','schedule','login','password'].includes(f.dataset.form))clearDirty();else if(['public-source','public-add','public-row-edit','public-import','academic-source','course-add','academic-students','academic-import'].includes(f.dataset.form))markDirty();}catch(error){showUIError(error);if(error.status===409)toast('发生版本冲突。当前表单未覆盖远端数据，请刷新并核对。',true);}finally{if(b?.isConnected)b.disabled=false;}});
document.addEventListener('input',e=>{const t=e.target;if(t.closest('form[data-form=public-save],form[data-form=academic-save],form[data-form=annotation],form[data-form=instructions],form[data-form=schedule]'))markDirty();if(t.dataset.filter){const parent=get(t.dataset.filter);if(parent)for(const row of parent.querySelectorAll('[data-search]')){row.dataset.searchHidden=String(!row.dataset.search.toLocaleLowerCase().includes(t.value.trim().toLocaleLowerCase()));row.hidden=row.dataset.searchHidden==='true'||row.dataset.columnHidden==='true';}if(parent)BNUCollections.refresh(parent);}if(t.dataset.publicScore!==undefined)S.publicRows[Number(t.dataset.publicScore)].score=t.value;});
document.addEventListener('change',async e=>{const t=e.target;try{
 if(t.dataset.upload==='evidence')await addFiles(t.files);
 if(t.hasAttribute('data-review-status')){await applyReviewFilters('attention');}
 if(t.hasAttribute('data-review-filter')){await applyReviewFilters(t.value);}
 if(t.hasAttribute('data-category-level')){get('category-picker').outerHTML=categoryPicker(t.value);}
 if(t.hasAttribute('data-public-version')){if(hasUnsavedWork()&&!window.confirm('切换版本会放弃未保存的修改，是否继续？')){t.value=S.publicEdit.revision;return;}clearDirty();location.hash='#/public-lists/'+S.publicEdit.id+'/'+t.value;}
 if(t.hasAttribute('data-public-rule-project')){S.publicContextProject=t.value||null;S.publicRuleNodes=t.value?(await api('/api/projects/'+t.value)).body.rule_versions.at(-1).nodes:S.template.nodes;const defaults=get('public-form').elements.default_category;const current=defaults.value;defaults.innerHTML=publicNodeOptions().map(o=>`<option value="${esc(o[0])}" ${o[0]===current?'selected':''}>${esc(o[1])}</option>`).join('');get('public-rows').innerHTML=publicRowsHTML(S.publicEdit.owner_id===S.me.id&&S.publicEdit.revision===(S.publicEdit.latest_revision||S.publicEdit.revision));enhanceCollections(get('main'));}
 if(t.hasAttribute('data-academic-student')){collectAcademic();S.academicStudent=t.value;await academicView();}
 if(t.dataset.feedbackStatus){await api('/api/ops/feedback/'+t.dataset.feedbackStatus,{method:'PATCH',body:{status:t.value}});toast('反馈状态已更新。');}
 }catch(err){showUIError(err);}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop="evidence"]'))e.preventDefault();});
document.addEventListener('drop',e=>{if(e.target.closest('[data-drop="evidence"]')){e.preventDefault();addFiles(e.dataTransfer.files).catch(err=>toast(err.message,true));}});
window.addEventListener('hashchange',()=>route());
window.addEventListener('beforeunload',e=>{if(hasUnsavedWork()){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>toast('网络已恢复，未完成的图片可以继续重试。'));
window.addEventListener('offline',()=>toast('网络已断开。已接收的原件保存在服务器，尚未上传的图片请保留此页面。',true));
document.addEventListener('DOMContentLoaded',async()=>{try{S.me=await api('/api/auth/me');await route();}catch{renderLogin();}},{once:true});
